// Banque de questions.
// d = domaine, o = objectif évalué (voir data/programme.js), q = énoncé, a = réponses,
// c = index de la bonne réponse (ou tableau d'index pour une question à réponses multiples), e = explication.
// L'ordre des réponses est mélangé à l'affichage.
const QUESTIONS = [
  // ── Domaine 1 : Bases mathématiques et calculs ───────────────────────────
  // 1.1 Fractions et pourcentages
  { d: 1, o: "1.1", q: "Que vaut 3/4 + 5/6 ?", a: ["8/10", "19/12", "15/24", "4/5"], c: 1, e: "On réduit au même dénominateur 12 : 3/4 = 9/12 et 5/6 = 10/12, soit 19/12. Additionner numérateurs et dénominateurs (8/10) est une erreur classique." },
  { d: 1, o: "1.1", q: "Parmi les égalités suivantes, lesquelles sont vraies ? (Choisissez 2 réponses)", a: ["1/2 + 1/3 = 5/6", "1/2 + 1/3 = 2/5", "2/3 × 3/4 = 1/2", "(1/2) ÷ (1/4) = 1/8", "3/5 + 1/5 = 4/10"], c: [0, 2], e: "1/2 + 1/3 = 3/6 + 2/6 = 5/6, et 2/3 × 3/4 = 6/12 = 1/2 après simplification. Diviser par 1/4 revient à multiplier par 4 : (1/2) ÷ (1/4) = 2. Enfin 3/5 + 1/5 = 4/5, pas 4/10." },
  { d: 1, o: "1.1", q: "Que vaut (2/5) ÷ (4/15) ?", a: ["8/75", "2/3", "3/2", "6/5"], c: 2, e: "Diviser par une fraction revient à multiplier par son inverse : 2/5 × 15/4 = 30/20 = 3/2." },
  { d: 1, o: "1.1", q: "Un service accueille 250 patients, dont 18 % sont diabétiques. Combien de patients diabétiques compte-t-il ?", a: ["18", "43", "45", "55"], c: 2, e: "Le pourcentage d’une quantité se calcule par N × t/100 : 250 × 18/100 = 45." },
  { d: 1, o: "1.1", q: "Le prix d’une boîte de médicament passe de 12,50 € à 15 €. Quelle est l’évolution en pourcentage ?", a: ["+20 %", "+2,5 %", "+16,7 %", "+25 %"], c: 0, e: "Évolution = (15 − 12,5) / 12,5 = 2,5 / 12,5 = 0,20, soit +20 %. Diviser par la valeur finale (2,5/15 ≈ 16,7 %) est une erreur fréquente : on divise toujours par la valeur initiale." },
  { d: 1, o: "1.1", q: "Une grandeur augmente de 10 %, puis diminue de 10 %. Quelle est son évolution globale ?", a: ["0 %", "−1 %", "+1 %", "−0,1 %"], c: 1, e: "On multiplie les coefficients multiplicateurs : 1,10 × 0,90 = 0,99, soit une baisse de 1 %. Les pourcentages successifs ne s’additionnent pas." },
  { d: 1, o: "1.1", q: "Après une baisse de 25 %, de quel pourcentage une valeur doit-elle augmenter pour retrouver sa valeur initiale ?", a: ["+25 %", "+33,3 %", "+75 %", "+20 %"], c: 1, e: "La baisse correspond au coefficient 0,75. Pour revenir à la valeur initiale, il faut multiplier par 1/0,75 ≈ 1,333, soit une hausse d’environ 33,3 %." },
  { d: 1, o: "1.1", q: "Quel est le coefficient multiplicateur associé à une baisse de 12 % ?", a: ["1,12", "0,88", "0,12", "−0,12"], c: 1, e: "Une baisse de t % correspond au coefficient multiplicateur 1 − t/100 = 1 − 0,12 = 0,88." },

  // 1.2 Puissances
  { d: 1, o: "1.2", q: "Que vaut 10³ × 10⁻⁵ / 10⁻⁴ ?", a: ["10⁻⁶", "10²", "10⁻²", "10¹²"], c: 1, e: "On additionne et soustrait les exposants : 3 + (−5) − (−4) = 2, donc 10². Attention au signe quand on divise par une puissance négative." },
  { d: 1, o: "1.2", q: "Quelle est la valeur de (2³)² ?", a: ["2⁵", "2⁹", "2⁶", "2⁸"], c: 2, e: "(aⁿ)ᵐ = aⁿˣᵐ : (2³)² = 2⁶ = 64. On multiplie les exposants, on ne les additionne pas (2⁵) et on ne les élève pas (2⁹)." },
  { d: 1, o: "1.2", q: "Que vaut 5⁻² ?", a: ["−25", "−10", "0,04", "0,1"], c: 2, e: "a⁻ⁿ = 1/aⁿ : 5⁻² = 1/25 = 0,04. Un exposant négatif ne rend pas le résultat négatif." },
  { d: 1, o: "1.2", q: "Pour a ≠ 0, à quoi se simplifie a⁵ × a⁻³ / a² ?", a: ["a⁴", "1", "a⁻¹⁰", "a⁶"], c: 1, e: "Exposant : 5 + (−3) − 2 = 0, et a⁰ = 1 pour a ≠ 0." },
  { d: 1, o: "1.2", q: "Que vaut (3 × 10²)² ?", a: ["3 × 10⁴", "9 × 10²", "9 × 10⁴", "6 × 10⁴"], c: 2, e: "(ab)ⁿ = aⁿbⁿ : 3² × (10²)² = 9 × 10⁴. On élève chacun des deux facteurs au carré." },
  { d: 1, o: "1.2", q: "Lesquelles de ces égalités sont vraies ? (Choisissez 2 réponses)", a: ["2³ × 2⁴ = 2⁷", "2³ + 2⁴ = 2⁷", "(2 × 5)³ = 2³ × 5³", "(2³)⁴ = 2⁷", "2⁰ = 0"], c: [0, 2], e: "aⁿ × aᵐ = aⁿ⁺ᵐ et (ab)ⁿ = aⁿbⁿ. En revanche, une somme de puissances ne se simplifie pas (8 + 16 = 24 ≠ 128), (2³)⁴ = 2¹², et 2⁰ = 1." },
  { d: 1, o: "1.2", q: "Un adulte a environ 5 L de sang contenant environ 5 × 10¹² hématies par litre. Quel est l’ordre de grandeur du nombre total d’hématies ?", a: ["2,5 × 10¹³", "2,5 × 10¹²", "5 × 10¹⁷", "25 × 10¹⁴"], c: 0, e: "5 × 5 × 10¹² = 25 × 10¹² = 2,5 × 10¹³. Avec les puissances de 10, on multiplie les mantisses et on additionne les exposants." },

  // 1.3 Racines
  { d: 1, o: "1.3", q: "Que vaut √0,0004 ?", a: ["0,2", "0,02", "0,002", "0,0002"], c: 1, e: "0,0004 = 4 × 10⁻⁴, donc √0,0004 = √4 × √(10⁻⁴) = 2 × 10⁻² = 0,02. Vérification : 0,02² = 0,0004." },
  { d: 1, o: "1.3", q: "Quelle est l’écriture simplifiée de √50 ?", a: ["25√2", "5√2", "2√5", "10√5"], c: 1, e: "√50 = √(25 × 2) = √25 × √2 = 5√2, grâce à la propriété √(ab) = √a × √b." },
  { d: 1, o: "1.3", q: "En utilisant l’écriture √a = a^(1/2), que vaut √(10⁻⁶) ?", a: ["10⁻³", "10⁻⁴", "10⁻¹²", "10³"], c: 0, e: "√(10⁻⁶) = (10⁻⁶)^(1/2) = 10⁻³ : prendre la racine carrée divise l’exposant par 2." },
  { d: 1, o: "1.3", q: "Quelle est la valeur de √(9 + 16) ?", a: ["7", "5", "25", "12,5"], c: 1, e: "√(9 + 16) = √25 = 5. Le piège est d’écrire √9 + √16 = 7 : la racine d’une somme n’est pas la somme des racines." },
  { d: 1, o: "1.3", q: "Pour x = −4, que vaut √(x²) ?", a: ["−4", "4", "±4", "16"], c: 1, e: "√(x²) = |x|. Pour x = −4, x² = 16 et √16 = 4 : une racine carrée est toujours positive ou nulle." },
  { d: 1, o: "1.3", q: "Que vaut √8 × √2 ?", a: ["√10", "4", "16", "2√10"], c: 1, e: "√8 × √2 = √16 = 4, par la propriété des racines √a × √b = √(ab)." },

  // 1.4 Équations
  { d: 1, o: "1.4", q: "Quelle est la solution de l’équation du premier degré 5x − 3 = 2x + 9 ?", a: ["x = 2", "x = 4", "x = 12", "x = −4"], c: 1, e: "5x − 2x = 9 + 3, donc 3x = 12 et x = 4. Vérification : 5 × 4 − 3 = 17 et 2 × 4 + 9 = 17." },
  { d: 1, o: "1.4", q: "Quelles sont les solutions de l’équation du second degré x² − 7x + 12 = 0 ?", a: ["3 et 4", "−3 et −4", "2 et 6", "Aucune solution réelle"], c: 0, e: "Δ = 49 − 48 = 1, donc x = (7 ± 1)/2, soit 3 et 4. Vérification : somme 7 = −b/a et produit 12 = c/a." },
  { d: 1, o: "1.4", q: "Combien de solutions réelles l’équation 2x² + 3x + 5 = 0 possède-t-elle ?", a: ["Aucune", "Une solution double", "Deux", "Une infinité"], c: 0, e: "Δ = b² − 4ac = 9 − 40 = −31 < 0 : l’équation n’a aucune solution réelle." },
  { d: 1, o: "1.4", q: "Quelles sont les solutions de l’équation x² = 49 ?", a: ["7 seulement", "7 et −7", "24,5", "49 et −49"], c: 1, e: "x² = 49 équivaut à x = 7 ou x = −7. Oublier la solution négative est une erreur fréquente." },
  { d: 1, o: "1.4", q: "Dans la formule C = n / V, on veut isoler la variable V. Quelle expression obtient-on ?", a: ["V = n × C", "V = n / C", "V = C / n", "V = n − C"], c: 1, e: "C = n/V donne C × V = n, puis V = n/C. Vérification : n/(n/C) = C." },
  { d: 1, o: "1.4", q: "L’IMC vaut m / t² (m en kg, t en m). Quelle est la masse d’une personne de 1,80 m dont l’IMC vaut 25 ?", a: ["45 kg", "72 kg", "81 kg", "90 kg"], c: 2, e: "On isole m : m = IMC × t² = 25 × 1,80² = 25 × 3,24 = 81 kg. Utiliser t au lieu de t² donne 45 kg." },
  { d: 1, o: "1.4", q: "Quelles sont les solutions de l’équation x(x − 5) = 0 ? (Choisissez 2 réponses)", a: ["0", "5", "−5", "1", "2,5"], c: [0, 1], e: "Un produit est nul si et seulement si l’un de ses facteurs est nul : x = 0 ou x − 5 = 0, soit x = 5." },

  // 1.5 Proportions
  { d: 1, o: "1.5", q: "Un sirop contient 120 mg de principe actif pour 5 mL. Quel volume administrer pour une dose de 300 mg ?", a: ["7,5 mL", "12,5 mL", "25 mL", "2 mL"], c: 1, e: "Règle de trois : 120 mg ↔ 5 mL, donc 1 mg ↔ 5/120 mL et 300 mg ↔ 300 × 5/120 = 12,5 mL." },
  { d: 1, o: "1.5", q: "Une poche de perfusion contient 1 g de médicament dans 250 mL. Quelle quantité de médicament contiennent 60 mL de cette poche ?", a: ["150 mg", "240 mg", "4 mg", "416 mg"], c: 1, e: "La quantité est proportionnelle au volume : 1000 mg × 60/250 = 240 mg (soit 4 mg/mL × 60 mL)." },
  { d: 1, o: "1.5", q: "Quel volume d’une solution à 5 g/L faut-il prélever pour préparer 250 mL d’une solution à 0,5 g/L ?", a: ["2,5 mL", "25 mL", "50 mL", "225 mL"], c: 1, e: "Lors d’une dilution, C₁V₁ = C₂V₂ : V₁ = 0,5 × 250 / 5 = 25 mL, que l’on complète jusqu’à 250 mL." },
  { d: 1, o: "1.5", q: "On prélève 5 mL d’une solution que l’on complète avec de l’eau jusqu’à 100 mL. Quel est le facteur de dilution ?", a: ["5", "19", "20", "95"], c: 2, e: "F = V final / V prélevé = 100 / 5 = 20. La concentration est divisée par 20." },
  { d: 1, o: "1.5", q: "On ajoute 40 mL d’eau à 10 mL d’une solution à 2 g/L. Quelle est la nouvelle concentration ?", a: ["0,5 g/L", "0,4 g/L", "8 g/L", "0,2 g/L"], c: 1, e: "Le volume final est 10 + 40 = 50 mL, soit un facteur de dilution de 5 : 2/5 = 0,4 g/L. Utiliser 40 mL comme volume final (0,5 g/L) est le piège classique." },
  { d: 1, o: "1.5", q: "Un médicament est prescrit à 15 mg/kg. Quelle dose donner à un enfant de 22 kg ?", a: ["330 mg", "300 mg", "37 mg", "1,47 mg"], c: 0, e: "La dose est proportionnelle au poids : 15 × 22 = 330 mg." },
  { d: 1, o: "1.5", q: "Avec un perfuseur standard, 20 gouttes correspondent à 1 mL. Quel volume passe en 1 heure à 20 gouttes par minute ?", a: ["20 mL", "60 mL", "400 mL", "1200 mL"], c: 1, e: "20 gouttes par minute = 1 mL par minute, donc 60 mL en 60 minutes. 1200 est le nombre de gouttes, pas de mL." },

  // 1.6 Conversions
  { d: 1, o: "1.6", q: "À combien de microgrammes correspondent 0,25 mg ?", a: ["25 µg", "250 µg", "2,5 µg", "2500 µg"], c: 1, e: "1 mg = 10³ µg, donc 0,25 mg = 250 µg." },
  { d: 1, o: "1.6", q: "À combien de litres correspond 1 m³ ?", a: ["100 L", "1000 L", "10 L", "10⁶ L"], c: 1, e: "1 L = 1 dm³ et 1 m³ = 10³ dm³ = 1000 L. 10⁶ correspond au nombre de cm³ (ou de mL) dans 1 m³." },
  { d: 1, o: "1.6", q: "Une glycémie vaut 1,10 g/L. Quelle est sa valeur en mg/dL ?", a: ["11 mg/dL", "110 mg/dL", "1100 mg/dL", "1,1 mg/dL"], c: 1, e: "1,10 g/L = 1100 mg/L, et 1 L = 10 dL, donc 1100/10 = 110 mg/dL." },
  { d: 1, o: "1.6", q: "Une solution de glucose (M = 180 g/mol) a une concentration de 5 mmol/L. Quelle est sa concentration massique ?", a: ["36 g/L", "0,9 g/L", "9 g/L", "0,028 g/L"], c: 1, e: "Cm = C × M = 5 × 10⁻³ mol/L × 180 g/mol = 0,9 g/L. Oublier la conversion des mmol en mol donne 900 g/L." },
  { d: 1, o: "1.6", q: "À combien de m³ correspond 1 cm³ ?", a: ["10⁻³ m³", "10⁻⁶ m³", "10⁻² m³", "10⁻⁹ m³"], c: 1, e: "1 cm = 10⁻² m, donc 1 cm³ = (10⁻²)³ m³ = 10⁻⁶ m³ : pour une unité cubique, on élève le facteur au cube." },
  { d: 1, o: "1.6", q: "Parmi les unités suivantes, lesquelles sont des unités SI de base ? (Choisissez 2 réponses)", a: ["Le kilogramme", "La mole", "Le litre", "Le gramme", "Le degré Celsius"], c: [0, 1], e: "Les unités SI de base comprennent le mètre, le kilogramme, la seconde, l’ampère, le kelvin, la mole et la candela. Le litre et le degré Celsius sont des unités usuelles, et l’unité de base de masse est le kilogramme, pas le gramme." },
  { d: 1, o: "1.6", q: "On dissout 5 g de NaCl dans de l’eau pour obtenir 500 mL de solution. Quelle est la concentration massique ?", a: ["2,5 g/L", "10 g/L", "0,01 g/L", "100 g/L"], c: 1, e: "Cm = m / V = 5 g / 0,5 L = 10 g/L. Il faut convertir 500 mL en 0,5 L avant de diviser." },

  // 1.7 Notation scientifique
  { d: 1, o: "1.7", q: "Quelle est l’écriture scientifique de 0,000 037 ?", a: ["3,7 × 10⁻⁵", "3,7 × 10⁻⁶", "37 × 10⁻⁶", "0,37 × 10⁻⁴"], c: 0, e: "En écriture scientifique, la mantisse est comprise entre 1 et 10 (exclu) : 3,7 × 10⁻⁵. 37 × 10⁻⁶ et 0,37 × 10⁻⁴ ont la bonne valeur, mais ne sont pas des écritures scientifiques." },
  { d: 1, o: "1.7", q: "Que vaut (4 × 10³) × (5 × 10⁻⁸) en écriture scientifique ?", a: ["2 × 10⁻⁵", "2 × 10⁻⁴", "20 × 10⁻⁴", "9 × 10⁻⁵"], c: 1, e: "4 × 5 = 20 et 10³ × 10⁻⁸ = 10⁻⁵, soit 20 × 10⁻⁵ = 2 × 10⁻⁴ après réajustement de la mantisse." },
  { d: 1, o: "1.7", q: "Que vaut (6 × 10⁻³) / (3 × 10⁻⁷) ?", a: ["2 × 10⁴", "2 × 10⁻¹⁰", "2 × 10⁻⁴", "3 × 10⁴"], c: 0, e: "6/3 = 2 et 10⁻³ / 10⁻⁷ = 10⁻³⁺⁷ = 10⁴, soit 2 × 10⁴." },
  { d: 1, o: "1.7", q: "Une bactérie comme Escherichia coli mesure quelques micromètres. Quel est l’ordre de grandeur de sa taille ?", a: ["10⁻⁶ m", "10⁻³ m", "10⁻⁹ m", "10⁻¹² m"], c: 0, e: "1 µm = 10⁻⁶ m. 10⁻³ m est l’ordre du millimètre, 10⁻⁹ m celui des molécules." },
  { d: 1, o: "1.7", q: "Combien de molécules contiennent 0,5 mol de glucose ? (nombre d’Avogadro : 6,02 × 10²³ mol⁻¹)", a: ["3,01 × 10²²", "3,01 × 10²³", "12,04 × 10²³", "6,02 × 10²²"], c: 1, e: "N = n × Nₐ = 0,5 × 6,02 × 10²³ = 3,01 × 10²³ molécules." },
  { d: 1, o: "1.7", q: "Quel est l’ordre de grandeur de 8 700 ?", a: ["10³", "10⁴", "10⁵", "10²"], c: 1, e: "8 700 = 8,7 × 10³. La mantisse 8,7 étant proche de 10, la puissance de 10 la plus proche est 10⁴." },

  // ── Domaine 2 : Fonctions, exponentielles et logarithmes ─────────────────
  // 2.1 Fonctions
  { d: 2, o: "2.1", q: "Quel est l’ensemble de définition de f(x) = 1 / (x − 2) ?", a: ["ℝ \\ {2}", "]2 ; +∞[", "ℝ", "ℝ \\ {0}"], c: 0, e: "On ne peut pas diviser par 0 : il faut x − 2 ≠ 0, soit x ≠ 2. L’ensemble de définition est ℝ privé de 2." },
  { d: 2, o: "2.1", q: "Quel est l’ensemble de définition de g(x) = √(x + 3) ?", a: ["]−3 ; +∞[", "[−3 ; +∞[", "[3 ; +∞[", "ℝ"], c: 1, e: "La racine carrée exige x + 3 ≥ 0, soit x ≥ −3. La valeur −3 est incluse car √0 = 0 existe." },
  { d: 2, o: "2.1", q: "Soit f(x) = x² − 1. Quelle est l’image de −2 par f ?", a: ["−5", "3", "5", "−3"], c: 1, e: "f(−2) = (−2)² − 1 = 4 − 1 = 3. Attention : (−2)² = 4 et non −4." },
  { d: 2, o: "2.1", q: "Soit f(x) = x² − 1. Quels sont les antécédents de 8 par f ?", a: ["63", "3 seulement", "3 et −3", "√7 et −√7"], c: 2, e: "On résout x² − 1 = 8, soit x² = 9 : x = 3 ou x = −3. 63 est l’image de 8, pas un antécédent." },
  { d: 2, o: "2.1", q: "Parmi les fonctions usuelles suivantes, lesquelles sont définies sur ℝ tout entier ? (Choisissez 2 réponses)", a: ["x ↦ eˣ", "x ↦ x²", "x ↦ ln x", "x ↦ 1/x", "x ↦ √x"], c: [0, 1], e: "L’exponentielle et la fonction carré sont définies sur ℝ. ln est définie sur ]0 ; +∞[, l’inverse sur ℝ privé de 0 et la racine carrée sur [0 ; +∞[." },
  { d: 2, o: "2.1", q: "Quel est l’ensemble de définition de h(x) = ln(5 − x) ?", a: ["]−∞ ; 5[", "]5 ; +∞[", "]−∞ ; 5]", "ℝ \\ {5}"], c: 0, e: "Le logarithme n’existe que pour un argument strictement positif : 5 − x > 0, soit x < 5. La valeur 5 est exclue car ln 0 n’existe pas." },

  // 2.2 Variations
  { d: 2, o: "2.2", q: "Quelle est la dérivée de f(x) = 3x⁴ ?", a: ["3x³", "12x³", "12x⁴", "4x³"], c: 1, e: "(xⁿ)′ = n·xⁿ⁻¹ et (ku)′ = ku′ : f′(x) = 3 × 4x³ = 12x³." },
  { d: 2, o: "2.2", q: "Quelle est la dérivée de f(x) = e^(−3x) ?", a: ["e^(−3x)", "−3e^(−3x)", "−3x·e^(−3x − 1)", "3e^(−3x)"], c: 1, e: "(e^u)′ = u′e^u avec u = −3x, u′ = −3 : f′(x) = −3e^(−3x)." },
  { d: 2, o: "2.2", q: "Quelle est la dérivée de f(x) = ln(x² + 1) ?", a: ["1 / (x² + 1)", "2x / (x² + 1)", "2x·ln(x² + 1)", "1 / (2x)"], c: 1, e: "(ln u)′ = u′/u avec u = x² + 1 et u′ = 2x : f′(x) = 2x / (x² + 1)." },
  { d: 2, o: "2.2", q: "Soit f(x) = x² − 6x + 1. Quel extremum f admet-elle ?", a: ["Un minimum égal à −8, atteint en x = 3", "Un maximum égal à −8, atteint en x = 3", "Un minimum égal à 3, atteint en x = −8", "Un minimum égal à 1, atteint en x = 0"], c: 0, e: "f′(x) = 2x − 6 s’annule en x = 3 en passant du négatif au positif : f décroît puis croît, d’où un minimum f(3) = 9 − 18 + 1 = −8." },
  { d: 2, o: "2.2", q: "Soit f(x) = x·e^(−x) sur [0 ; +∞[, de dérivée f′(x) = (1 − x)e^(−x). Sur quel intervalle f est-elle croissante ?", a: ["[0 ; 1]", "[1 ; +∞[", "[0 ; +∞[", "f n’est croissante sur aucun intervalle"], c: 0, e: "e^(−x) > 0, donc f′ a le signe de 1 − x : positif sur [0 ; 1], négatif ensuite. Le sens de variation se lit sur le signe de la dérivée." },
  { d: 2, o: "2.2", q: "Après une prise orale, la concentration d’un médicament est modélisée par C(t) = 10t·e^(−0,5t) (t en heures). À quel instant est-elle maximale ?", a: ["0,5 h", "2 h", "5 h", "10 h"], c: 1, e: "C′(t) = 10e^(−0,5t) − 5t·e^(−0,5t) = e^(−0,5t)(10 − 5t). La dérivée s’annule en t = 2 et passe du positif au négatif : la concentration est maximale à 2 h." },
  { d: 2, o: "2.2", q: "On sait que f′(a) = 0 pour une fonction f dérivable. Que peut-on en conclure ?", a: ["f admet forcément un extremum en a", "La tangente en a est horizontale ; f n’a un extremum en a que si f′ change de signe en a", "f est constante", "f(a) = 0"], c: 1, e: "f′(a) = 0 signifie une tangente horizontale. Pour f(x) = x³, f′(0) = 0 mais f est croissante sur ℝ : il n’y a extremum que si f′ change de signe." },

  // 2.3 Exponentielle
  { d: 2, o: "2.3", q: "À quoi est égal e² × e³ ?", a: ["e⁵", "e⁶", "2e⁵", "e^(2/3)"], c: 0, e: "Propriété algébrique de l’exponentielle : e^a × e^b = e^(a+b), donc e² × e³ = e⁵." },
  { d: 2, o: "2.3", q: "Pour tout réel x, à quoi est égal e^(3x) / e^x ?", a: ["e³", "e^(2x)", "e^(4x)", "3"], c: 1, e: "e^a / e^b = e^(a−b) : e^(3x − x) = e^(2x)." },
  { d: 2, o: "2.3", q: "Quelle est la limite de e^(−0,3t) quand t tend vers +∞ ?", a: ["1", "0", "+∞", "−∞"], c: 1, e: "Quand t → +∞, −0,3t → −∞, et eˣ → 0 quand x → −∞. C’est pourquoi une décroissance exponentielle tend vers 0." },
  { d: 2, o: "2.3", q: "Laquelle de ces affirmations sur la fonction exponentielle est vraie ?", a: ["eˣ > 0 pour tout réel x", "e⁰ = 0", "La fonction exponentielle est décroissante sur ℝ", "e^(−x) = −eˣ"], c: 0, e: "L’exponentielle est strictement positive et strictement croissante sur ℝ, avec e⁰ = 1. e^(−x) = 1/eˣ, qui reste positif." },
  { d: 2, o: "2.3", q: "À quoi est égal e^(−2) ?", a: ["−e²", "1 / e²", "−2e", "e^(1/2)"], c: 1, e: "e^(−a) = 1/eᵃ : e^(−2) = 1/e² ≈ 0,135, un nombre positif." },
  { d: 2, o: "2.3", q: "Pour tous réels a et b, quelles égalités sont vraies ? (Choisissez 2 réponses)", a: ["e^(a+b) = eᵃ × eᵇ", "(eᵃ)ᵇ = e^(ab)", "e^(a+b) = eᵃ + eᵇ", "e^(ab) = eᵃ × eᵇ", "e^(a−b) = eᵃ − eᵇ"], c: [0, 1], e: "L’exponentielle transforme les sommes en produits : e^(a+b) = eᵃeᵇ, et (eᵃ)ᵇ = e^(ab). Elle ne transforme pas une somme en somme, ni un produit en produit." },
  { d: 2, o: "2.3", q: "Quelle est la limite de eˣ / x³ quand x tend vers +∞ ?", a: ["0", "+∞", "1", "3"], c: 1, e: "Par croissances comparées, l’exponentielle l’emporte sur toute puissance de x en +∞ : eˣ / x³ → +∞." },

  // 2.4 Logarithme
  { d: 2, o: "2.4", q: "Pour a > 0 et b > 0, à quoi est égal ln(a²b) ?", a: ["2 ln a + ln b", "2(ln a + ln b)", "ln(2a) + ln b", "(ln a)² + ln b"], c: 0, e: "Propriétés du logarithme : ln(a²b) = ln(a²) + ln b = 2 ln a + ln b." },
  { d: 2, o: "2.4", q: "Que vaut le logarithme décimal log(0,001) ?", a: ["3", "−3", "−2", "−4"], c: 1, e: "0,001 = 10⁻³ et log(10ⁿ) = n, donc log(0,001) = −3." },
  { d: 2, o: "2.4", q: "Quelle est la solution de l’équation e^(2x) = 7 ?", a: ["x = ln 7 / 2", "x = ln(7/2)", "x = 2 ln 7", "x = e⁷ / 2"], c: 0, e: "On applique ln aux deux membres : 2x = ln 7, donc x = (ln 7)/2 ≈ 0,97." },
  { d: 2, o: "2.4", q: "Quelle est la solution de l’équation avec logarithme ln x = 3 ?", a: ["x = 3e", "x = e³", "x = ln 3", "x = 10³"], c: 1, e: "ln x = 3 équivaut à x = e³ ≈ 20,1. 10³ serait la solution de log x = 3 (logarithme décimal)." },
  { d: 2, o: "2.4", q: "Sachant que ln 2 ≈ 0,693, quelle est la valeur approchée de ln 8 ?", a: ["2,08", "5,54", "2,77", "0,35"], c: 0, e: "ln 8 = ln(2³) = 3 ln 2 ≈ 3 × 0,693 = 2,079. 5,54 correspondrait à 8 × ln 2, ce qui est faux." },
  { d: 2, o: "2.4", q: "Quelle est la solution de l’équation ln(x − 3) = 0 ?", a: ["x = 3", "x = 4", "x = e³", "Il n’y a pas de solution"], c: 1, e: "ln(x − 3) = 0 équivaut à x − 3 = e⁰ = 1, soit x = 4, qui respecte bien la condition x > 3." },
  { d: 2, o: "2.4", q: "Parmi ces affirmations sur le logarithme népérien, lesquelles sont vraies ? (Choisissez 2 réponses)", a: ["ln 1 = 0", "ln e = 1", "ln 0 = 1", "ln(a + b) = ln a + ln b pour a, b > 0", "ln(−1) = −ln 1"], c: [0, 1], e: "ln 1 = 0 et ln e = 1. ln n’est défini que pour x > 0 (ni ln 0 ni ln(−1) n’existent), et ln transforme les produits, pas les sommes, en sommes." },

  // 2.5 Applications biomédicales
  { d: 2, o: "2.5", q: "Une solution a un pH de 3. Quelle est sa concentration en ions H₃O⁺ ?", a: ["3 mol/L", "10⁻³ mol/L", "10³ mol/L", "10⁻¹¹ mol/L"], c: 1, e: "[H₃O⁺] = 10^(−pH) = 10⁻³ mol/L." },
  { d: 2, o: "2.5", q: "Le pH sanguin d’un patient passe de 7,4 à 7,1. Comment a évolué la concentration en ions H₃O⁺ ?", a: ["Elle a environ doublé", "Elle a été multipliée par 0,3", "Elle a été multipliée par 3", "Elle a été multipliée par 10"], c: 0, e: "Une baisse de 0,3 unité de pH multiplie [H₃O⁺] par 10^0,3 ≈ 2, car log 2 ≈ 0,3. Le pH suit une échelle logarithmique." },
  { d: 2, o: "2.5", q: "Une urine a une concentration [H₃O⁺] = 1 × 10⁻⁶ mol/L. Quel est son pH ?", a: ["−6", "6", "8", "10⁻⁶"], c: 1, e: "pH = −log[H₃O⁺] = −log(10⁻⁶) = 6." },
  { d: 2, o: "2.5", q: "Sous traitement, la charge virale d’un patient passe de 10⁶ à 10⁴ copies/mL. Comment décrire cette évolution ?", a: ["Elle a été divisée par 100 (baisse de 2 log)", "Elle a été divisée par 2", "Elle a diminué de 2 %", "Elle a été divisée par 20"], c: 0, e: "Sur une échelle logarithmique, passer de 10⁶ à 10⁴ représente 2 unités de log, soit une division par 10² = 100." },
  { d: 2, o: "2.5", q: "Sur un graphique dont l’ordonnée suit une échelle logarithmique, comment apparaît une croissance exponentielle ?", a: ["Comme une droite", "Comme une parabole", "Comme une droite horizontale", "Comme une hyperbole"], c: 0, e: "Si N = N₀e^(kt), alors ln N = ln N₀ + kt : le logarithme de N est une fonction affine du temps, donc une droite." },

  // ── Domaine 3 : Biomathématiques et modélisation ─────────────────────────
  // 3.1 Modélisation
  { d: 3, o: "3.1", q: "Une population augmente de 500 individus par jour, quel que soit son effectif. Quel modèle choisir ?", a: ["Un modèle linéaire N(t) = N₀ + 500t", "Un modèle exponentiel N(t) = N₀e^(500t)", "Un modèle constant", "Un modèle logarithmique"], c: 0, e: "Une variation constante par unité de temps correspond à un modèle linéaire. Le modèle exponentiel s’applique quand la variation est proportionnelle à l’effectif." },
  { d: 3, o: "3.1", q: "La vitesse d’élimination d’un médicament est proportionnelle à la quantité présente dans l’organisme. Quel modèle choisir ?", a: ["Une décroissance linéaire", "Une décroissance exponentielle", "Une croissance exponentielle", "Un modèle constant"], c: 1, e: "Hypothèse du modèle : dQ/dt = −kQ. La variation proportionnelle à la quantité conduit à Q(t) = Q₀e^(−kt), une décroissance exponentielle." },
  { d: 3, o: "3.1", q: "Pourquoi un modèle de croissance exponentielle d’une culture bactérienne n’est-il valable que sur une durée limitée ?", a: ["Parce que l’exponentielle finit par devenir négative", "Parce que l’épuisement des ressources du milieu finit par ralentir la croissance", "Parce qu’un modèle exponentiel est toujours décroissant", "Parce que les bactéries ne se divisent pas"], c: 1, e: "Les hypothèses du modèle (ressources illimitées) cessent d’être vraies : la croissance ralentit puis atteint une phase stationnaire. Tout modèle a un domaine de validité." },
  { d: 3, o: "3.1", q: "Dans le modèle C(t) = C₀e^(−kt) d’une concentration plasmatique, quelles sont la grandeur modélisée et la variable ?", a: ["La grandeur modélisée est la concentration C ; la variable est le temps t", "La grandeur modélisée est le temps t ; la variable est la concentration C", "La grandeur modélisée est k ; la variable est C₀", "La grandeur modélisée est C₀ ; la variable est k"], c: 0, e: "On décrit l’évolution de la concentration (grandeur modélisée) en fonction du temps (variable). C₀ et k sont des paramètres fixés pour un patient donné." },
  { d: 3, o: "3.1", q: "Une grandeur est multipliée par 1,5 toutes les heures. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["Sa variation est proportionnelle à sa valeur", "Un modèle exponentiel est adapté", "Elle augmente de la même quantité chaque heure", "Un modèle linéaire est adapté", "Elle double toutes les heures"], c: [0, 1], e: "Être multiplié par un facteur constant par unité de temps signifie une variation proportionnelle à la valeur : c’est le choix du modèle exponentiel. L’augmentation absolue grandit au cours du temps, et le facteur 1,5 n’est pas un doublement." },
  { d: 3, o: "3.1", q: "On mesure une grandeur aux temps 0, 1, 2 et 3 h : 100, 200, 400, 800. Quel modèle est adapté ?", a: ["Un modèle exponentiel, car le rapport entre deux valeurs successives est constant", "Un modèle linéaire, car les écarts entre valeurs successives sont constants", "Un modèle linéaire, car la grandeur augmente", "Aucun modèle ne convient"], c: 0, e: "Les rapports successifs valent tous 2, alors que les écarts (100, 200, 400) augmentent : c’est la signature d’un modèle exponentiel." },

  // 3.2 Croissance/décroissance
  { d: 3, o: "3.2", q: "Une population croît selon N(t) = N₀e^(0,05t), t en heures. Quel est son temps de doublement ?", a: ["Environ 6,9 h", "Environ 13,9 h", "20 h", "0,035 h"], c: 1, e: "Temps de doublement T₂ = ln 2 / k = 0,693 / 0,05 ≈ 13,9 h." },
  { d: 3, o: "3.2", q: "Un médicament est éliminé selon C(t) = C₀e^(−0,2t), t en heures. Quelle est sa demi-vie ?", a: ["Environ 3,5 h", "5 h", "0,14 h", "Environ 1,4 h"], c: 0, e: "Demi-vie t½ = ln 2 / k = 0,693 / 0,2 ≈ 3,5 h. 5 h correspond à 1/k, qui n’est pas la demi-vie." },
  { d: 3, o: "3.2", q: "Quelle fraction d’une quantité reste-t-il après 3 demi-vies ?", a: ["12,5 %", "25 %", "33 %", "3 %"], c: 0, e: "Après n demi-vies, il reste 1/2ⁿ : 1/2³ = 1/8 = 12,5 %." },
  { d: 3, o: "3.2", q: "Une population bactérienne augmente de 20 % par heure. Par combien est-elle multipliée en 3 heures ?", a: ["1,6", "1,728", "3,6", "1,2"], c: 1, e: "Taux de croissance de 20 % par heure : coefficient 1,2 par heure, donc 1,2³ = 1,728 en 3 h (+72,8 %), et non 3 × 20 % = 60 %." },
  { d: 3, o: "3.2", q: "Le temps de doublement d’une croissance exponentielle N₀e^(kt) dépend-il de la quantité initiale N₀ ?", a: ["Non, il ne dépend que de k", "Oui, il est proportionnel à N₀", "Oui, il est inversement proportionnel à N₀", "Il dépend de N₀ et du temps écoulé"], c: 0, e: "N₀e^(k(t+T)) = 2N₀e^(kt) donne e^(kT) = 2, soit T = ln 2 / k : N₀ disparaît du calcul." },
  { d: 3, o: "3.2", q: "Un médicament a une demi-vie de 8 h. Quelle est sa constante d’élimination k ?", a: ["Environ 0,087 h⁻¹", "Environ 11,5 h⁻¹", "0,125 h⁻¹", "5,5 h⁻¹"], c: 0, e: "t½ = ln 2 / k, donc k = ln 2 / t½ = 0,693 / 8 ≈ 0,087 h⁻¹." },
  { d: 3, o: "3.2", q: "Dans le modèle N(t) = N₀e^(kt), que signifie un taux de croissance k négatif ?", a: ["La grandeur décroît au cours du temps", "La grandeur croît au cours du temps", "La grandeur reste constante", "La valeur initiale N₀ est négative"], c: 0, e: "k > 0 donne une croissance, k < 0 une décroissance. Le signe de k ne renseigne pas sur N₀." },

  // 3.3 Équations différentielles simples
  { d: 3, o: "3.3", q: "Quelles sont les solutions de l’équation différentielle y′ = 4y ?", a: ["y = Ce^(4x), C réel", "y = 4eˣ + C", "y = Ce^(x/4)", "y = 4x + C"], c: 0, e: "Les solutions de y′ = ay sont y = Ce^(ax). Ici a = 4." },
  { d: 3, o: "3.3", q: "Quelle est la solution de y′ = −0,5y vérifiant la condition initiale y(0) = 8 ?", a: ["y(t) = 8e^(0,5t)", "y(t) = 8e^(−0,5t)", "y(t) = −0,5e^(8t)", "y(t) = 8 − 0,5t"], c: 1, e: "y = Ce^(−0,5t) et y(0) = C = 8, donc y(t) = 8e^(−0,5t)." },
  { d: 3, o: "3.3", q: "Quelle est la solution constante (état d’équilibre) de y′ = −2y + 6 ?", a: ["y = 3", "y = −3", "y = 6", "y = 12"], c: 0, e: "Une solution constante vérifie y′ = 0 : −2y + 6 = 0, soit y = 3. C’est aussi −b/a = −6/(−2)." },
  { d: 3, o: "3.3", q: "Une perfusion est modélisée par y′ = −0,2y + 4 avec y(0) = 0. Quelle est la solution ?", a: ["y(t) = 20 − 20e^(−0,2t)", "y(t) = 20e^(−0,2t)", "y(t) = 4 − 4e^(−0,2t)", "y(t) = 20 + 20e^(−0,2t)"], c: 0, e: "y = Ce^(−0,2t) − b/a avec −b/a = 20. La condition initiale y(0) = C + 20 = 0 donne C = −20, d’où y(t) = 20 − 20e^(−0,2t)." },
  { d: 3, o: "3.3", q: "Quelles sont les solutions de y′ = 3y − 6 ?", a: ["y = Ce^(3x) + 2", "y = Ce^(3x) − 2", "y = Ce^(3x) − 6", "y = Ce^(−3x) + 2"], c: 0, e: "Pour y′ = ay + b, y = Ce^(ax) − b/a. Avec a = 3 et b = −6 : −b/a = 6/3 = 2." },
  { d: 3, o: "3.3", q: "Lors de la résolution d’une équation différentielle du type y′ = ay, à quoi sert la condition initiale ?", a: ["À déterminer la constante C", "À déterminer le coefficient a", "À vérifier que la solution est positive", "Elle ne sert à rien"], c: 0, e: "L’équation fournit une famille de solutions Ce^(ax). La condition initiale y(0) = y₀ sélectionne l’unique solution : C = y₀." },
  { d: 3, o: "3.3", q: "On considère y′ = −0,1y + 2 pour t ≥ 0. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["La solution constante est y = 20", "Toutes les solutions tendent vers 20 quand t → +∞", "La solution constante est y = −20", "Toutes les solutions tendent vers +∞", "Les solutions sont de la forme Ce^(0,1t) + 20"], c: [0, 1], e: "Pour y′ = ay + b : équilibre −b/a = −2/(−0,1) = 20, et solutions Ce^(−0,1t) + 20. Comme a < 0, le terme exponentiel tend vers 0 et toutes les solutions tendent vers 20." },

  // 3.4 Modèles exponentiels
  { d: 3, o: "3.4", q: "Avec le modèle N(t) = N₀·e^(kt), N₀ = 1000 et k = 0,1 h⁻¹, quelle est la valeur de N au bout de 10 h ?", a: ["Environ 2718", "2000", "1100", "11 000"], c: 0, e: "N(10) = 1000 × e^(0,1 × 10) = 1000 × e ≈ 2718." },
  { d: 3, o: "3.4", q: "Une population passe de 200 à 800 bactéries en 5 heures, selon un modèle exponentiel. Quel est son taux de croissance k ?", a: ["Environ 0,28 h⁻¹", "0,6 h⁻¹", "120 h⁻¹", "Environ 1,39 h⁻¹"], c: 0, e: "k = ln(N₂/N₁)/(t₂ − t₁) = ln 4 / 5 ≈ 1,386 / 5 ≈ 0,28 h⁻¹. 1,39 est ln 4, sans division par la durée." },
  { d: 3, o: "3.4", q: "Si N(t) = N₀·e^(kt), quelle est l’allure du graphe de ln N en fonction de t ?", a: ["Une droite de pente k et d’ordonnée à l’origine ln N₀", "Une droite de pente N₀ et d’ordonnée à l’origine k", "Une parabole", "Une courbe exponentielle"], c: 0, e: "Linéarisation par le logarithme : ln N = ln N₀ + kt, fonction affine de t." },
  { d: 3, o: "3.4", q: "Avec le modèle N(t) = N₀e^(0,2t), par quel facteur N est-elle multipliée entre t = 2 et t = 5 ?", a: ["e^0,6 ≈ 1,82", "0,6", "e^0,2 ≈ 1,22", "Cela dépend de N₀"], c: 0, e: "N(5)/N(2) = e^(0,2 × 3) = e^0,6 ≈ 1,82. Sur une durée donnée, le facteur ne dépend que de kΔt, pas de N₀." },
  { d: 3, o: "3.4", q: "Après linéarisation, des mesures donnent ln N = 2 + 0,3t. Quels sont les paramètres du modèle N(t) = N₀e^(kt) ?", a: ["N₀ = e² ≈ 7,4 et k = 0,3", "N₀ = 2 et k = 0,3", "N₀ = 0,3 et k = 2", "N₀ = e² et k = e^0,3"], c: 0, e: "ln N = ln N₀ + kt : l’ordonnée à l’origine vaut ln N₀ = 2, donc N₀ = e², et la pente vaut k = 0,3." },
  { d: 3, o: "3.4", q: "Une concentration suit C(t) = 50e^(−0,1t), t en heures. Au bout de combien de temps vaut-elle 25 ?", a: ["Environ 6,9 h", "5 h", "25 h", "Environ 0,69 h"], c: 0, e: "50e^(−0,1t) = 25 donne e^(−0,1t) = 0,5, soit t = ln 2 / 0,1 ≈ 6,9 h : c’est la demi-vie." },

  // 3.5 Applications biologiques
  { d: 3, o: "3.5", q: "Une bactérie a un temps de génération de 20 minutes. Par combien une culture en phase exponentielle est-elle multipliée en 2 heures ?", a: ["6", "12", "32", "64"], c: 3, e: "2 heures = 6 générations de 20 min : la croissance bactérienne multiplie la population par 2⁶ = 64." },
  { d: 3, o: "3.5", q: "Après une injection, la concentration d’un médicament vaut 40 mg/L et sa demi-vie d’élimination est de 6 h. Quelle est la concentration 18 h plus tard ?", a: ["5 mg/L", "10 mg/L", "13,3 mg/L", "20 mg/L"], c: 0, e: "18 h = 3 demi-vies : 40 / 2³ = 5 mg/L. Diviser par 3 (13,3 mg/L) confond demi-vie et décroissance linéaire." },
  { d: 3, o: "3.5", q: "Pour l’élimination d’un médicament d’ordre 1, au bout de combien de demi-vies reste-t-il moins de 5 % de la dose ?", a: ["3", "4", "5", "10"], c: 2, e: "Après 4 demi-vies il reste 1/16 = 6,25 %, après 5 demi-vies 1/32 ≈ 3,1 %. C’est pourquoi on considère qu’un médicament est quasiment éliminé après 5 demi-vies." },
  { d: 3, o: "3.5", q: "Le technétium 99m a une période radioactive d’environ 6 heures. Quelle fraction de l’activité initiale reste-t-il après 24 heures ?", a: ["1/4", "1/8", "1/16", "1/24"], c: 2, e: "24 h = 4 périodes : la décroissance radioactive laisse (1/2)⁴ = 1/16 de l’activité initiale, soit 6,25 %." },
  { d: 3, o: "3.5", q: "L’iode 131 a une période d’environ 8 jours. Quelle fraction de l’activité initiale reste-t-il après 24 jours ?", a: ["1/3", "1/8", "1/16", "1/24"], c: 1, e: "24 jours = 3 périodes : il reste (1/2)³ = 1/8 de l’activité. La décroissance est exponentielle, pas linéaire (ce qui donnerait 0)." },
  { d: 3, o: "3.5", q: "Une culture contient 10³ bactéries et double toutes les 30 min en phase exponentielle. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["Après 2 h, elle contient 1,6 × 10⁴ bactéries", "Le modèle N(t) = 10³ × 2^(t/30), t en minutes, est adapté", "Après 2 h, elle contient 4 × 10³ bactéries", "La croissance restera exponentielle indéfiniment", "Après 1 h, elle contient 3 × 10³ bactéries"], c: [0, 1], e: "2 h = 4 doublements : 10³ × 2⁴ = 1,6 × 10⁴. Après 1 h, 2 doublements donnent 4 × 10³. La croissance bactérienne finit par ralentir quand le milieu s’épuise." },

  // ── Domaine 4 : Probabilités ────────────────────────────────────────────
  // 4.1 Événements
  { d: 4, o: "4.1", q: "Un événement A a une probabilité P(A) = 0,3. Quelle est la probabilité de l’événement contraire Ā ?", a: ["0,3", "0,7", "−0,3", "1,3"], c: 1, e: "P(Ā) = 1 − P(A) = 1 − 0,3 = 0,7." },
  { d: 4, o: "4.1", q: "On sait que P(A) = 0,5, P(B) = 0,4 et P(A ∩ B) = 0,2. Que vaut P(A ∪ B) ?", a: ["0,9", "0,7", "0,2", "0,5"], c: 1, e: "P(A ∪ B) = P(A) + P(B) − P(A ∩ B) = 0,5 + 0,4 − 0,2 = 0,7. Sans retirer l’intersection, on la compterait deux fois." },
  { d: 4, o: "4.1", q: "A et B sont deux événements incompatibles avec P(A) = 0,25 et P(B) = 0,35. Que vaut P(A ∪ B) ?", a: ["0,0875", "0,6", "0,1", "0,35"], c: 1, e: "Pour des événements incompatibles, P(A ∩ B) = 0, donc P(A ∪ B) = P(A) + P(B) = 0,6." },
  { d: 4, o: "4.1", q: "On lance un dé équilibré à six faces. Quelle est la probabilité d’obtenir un nombre pair ou un nombre supérieur ou égal à 5 ?", a: ["5/6", "2/3", "1/2", "1/3"], c: 1, e: "L’union des deux événements est {2, 4, 5, 6}, soit 4 issues sur 6 : 2/3. Additionner 3/6 + 2/6 compterait deux fois le 6." },
  { d: 4, o: "4.1", q: "On lance deux fois une pièce (P = pile, F = face) en notant l’ordre des résultats. Quel est l’univers Ω ?", a: ["{PP, PF, FP, FF}", "{PP, PF, FF}", "{P, F}", "{0, 1, 2}"], c: 0, e: "L’univers est l’ensemble de toutes les issues possibles : 4 issues ordonnées. {PP, PF, FF} oublie que PF et FP sont deux issues distinctes." },
  { d: 4, o: "4.1", q: "Trois patients reçoivent un traitement. Quel est l’événement contraire de « au moins un patient guérit » ?", a: ["Aucun patient ne guérit", "Au plus un patient guérit", "Au moins un patient ne guérit pas", "Tous les patients guérissent"], c: 0, e: "Le contraire de « au moins un » est « aucun ». C’est la base de l’astuce P(au moins un) = 1 − P(aucun)." },
  { d: 4, o: "4.1", q: "Une urne contient 3 boules rouges, 5 bleues et 2 vertes. On tire une boule au hasard. Quelle est la probabilité qu’elle ne soit pas bleue ?", a: ["1/2", "3/10", "1/5", "5/10"], c: 0, e: "Par équiprobabilité, P(bleue) = 5/10. L’événement contraire a pour probabilité 1 − 5/10 = 1/2 (5 boules rouges ou vertes sur 10)." },
  { d: 4, o: "4.1", q: "A = « le patient est fumeur » et B = « le patient est hypertendu ». Que représente l’intersection A ∩ B ?", a: ["Le patient est fumeur et hypertendu", "Le patient est fumeur ou hypertendu", "Le patient n’est ni fumeur ni hypertendu", "Le patient est fumeur mais pas hypertendu"], c: 0, e: "L’intersection A ∩ B correspond à « A et B » : les deux caractères sont présents simultanément." },
  { d: 4, o: "4.1", q: "A = « le patient est fumeur » et B = « le patient est hypertendu ». Que représente l’union A ∪ B ?", a: ["Le patient est fumeur et hypertendu", "Le patient présente au moins l’un des deux caractères", "Le patient présente exactement un des deux caractères", "Le patient n’est ni fumeur ni hypertendu"], c: 1, e: "L’union A ∪ B correspond à « A ou B » au sens large : au moins l’un des deux, éventuellement les deux." },
  { d: 4, o: "4.1", q: "On lance un dé à six faces. Parmi ces couples d’événements, lequel est formé d’événements incompatibles ?", a: ["« Obtenir 1 » et « obtenir un nombre pair »", "« Obtenir un nombre pair » et « obtenir 6 »", "« Obtenir un nombre ≤ 3 » et « obtenir un nombre impair »", "« Obtenir 2 » et « obtenir un nombre premier »"], c: 0, e: "Des événements incompatibles ne peuvent pas se réaliser ensemble : 1 n’est pas pair. Les autres couples partagent une issue (6 ; 1 et 3 ; 2)." },
  { d: 4, o: "4.1", q: "Dans une promotion, 60 % des étudiants sont des filles, 25 % portent des lunettes et 15 % sont des filles portant des lunettes. Quelle est la proportion d’étudiants qui ne sont ni des filles ni porteurs de lunettes ?", a: ["30 %", "15 %", "70 %", "40 %"], c: 0, e: "P(F ∪ L) = 0,60 + 0,25 − 0,15 = 0,70. « Ni l’un ni l’autre » est le contraire de l’union : 1 − 0,70 = 0,30." },
  { d: 4, o: "4.1", q: "Soit A et B deux événements quelconques. Quelles affirmations sont toujours vraies ? (Choisissez 2 réponses)", a: ["P(Ā) = 1 − P(A)", "P(A ∪ B) = P(A) + P(B) − P(A ∩ B)", "P(A ∪ B) = P(A) + P(B)", "P(A ∩ B) = P(A) × P(B)", "P(A) + P(B) ≤ 1"], c: [0, 1], e: "Les deux premières formules sont générales. P(A ∪ B) = P(A) + P(B) exige des événements incompatibles, et P(A ∩ B) = P(A)P(B) des événements indépendants. P(A) + P(B) peut dépasser 1." },

  // 4.2 Probabilité conditionnelle
  { d: 4, o: "4.2", q: "On sait que P(A ∩ B) = 0,12 et P(B) = 0,4. Que vaut P(A|B) ?", a: ["0,3", "0,048", "0,12", "0,52"], c: 0, e: "P(A|B) = P(A ∩ B) / P(B) = 0,12 / 0,4 = 0,3." },
  { d: 4, o: "4.2", q: "On sait que P(A) = 0,5, P(B) = 0,4 et P(A ∩ B) = 0,1. Que vaut P(B|A) ?", a: ["0,25", "0,2", "0,05", "0,1"], c: 1, e: "P(B|A) = P(A ∩ B) / P(A) = 0,1 / 0,5 = 0,2. Diviser par P(B) donnerait P(A|B) = 0,25." },
  { d: 4, o: "4.2", q: "Sur 200 patients, 80 sont fumeurs, dont 30 atteints de BPCO ; parmi les 120 non-fumeurs, 10 ont une BPCO. Quelle est la probabilité qu’un patient ait une BPCO sachant qu’il est fumeur ?", a: ["0,15", "0,375", "0,75", "0,2"], c: 1, e: "On se restreint aux 80 fumeurs : P(BPCO | fumeur) = 30/80 = 0,375. 0,15 = 30/200 est P(BPCO ∩ fumeur)." },
  { d: 4, o: "4.2", q: "Sur 200 patients, 80 sont fumeurs, dont 30 atteints de BPCO ; parmi les 120 non-fumeurs, 10 ont une BPCO. Quelle est la probabilité qu’un patient soit fumeur sachant qu’il a une BPCO ?", a: ["0,375", "0,75", "0,15", "0,4"], c: 1, e: "On se restreint aux 40 patients atteints de BPCO : 30 sont fumeurs, soit 30/40 = 0,75. P(fumeur | BPCO) diffère de P(BPCO | fumeur)." },
  { d: 4, o: "4.2", q: "On sait que P(A|B) = 0,35. Que vaut P(Ā|B) ?", a: ["0,35", "0,65", "Impossible à calculer sans P(B)", "0,1225"], c: 1, e: "Sachant B, A et Ā sont complémentaires : P(Ā|B) = 1 − P(A|B) = 0,65." },
  { d: 4, o: "4.2", q: "La probabilité d’avoir de la fièvre sachant qu’on a la grippe vaut 0,9. Que peut-on dire de la probabilité d’avoir la grippe sachant qu’on a de la fièvre ?", a: ["Elle vaut 0,9", "Elle vaut 0,1", "On ne peut pas la déduire sans autres informations", "Elle vaut 1/0,9"], c: 2, e: "P(A|B) ≠ P(B|A) en général. Pour inverser le conditionnement, il faut aussi la fréquence de la grippe et celle de la fièvre (formule de Bayes)." },
  { d: 4, o: "4.2", q: "On tire une carte d’un jeu de 52 cartes. Sachant que c’est une figure (valet, dame ou roi), quelle est la probabilité que ce soit un roi ?", a: ["1/13", "1/3", "4/52", "1/4"], c: 1, e: "Il y a 12 figures, dont 4 rois : P(roi | figure) = 4/12 = 1/3. Conditionner revient à restreindre l’univers aux figures." },
  { d: 4, o: "4.2", q: "On lance un dé équilibré. Sachant que le résultat est pair, quelle est la probabilité d’avoir obtenu 6 ?", a: ["1/6", "1/3", "1/2", "1/12"], c: 1, e: "Sachant « pair », les issues possibles sont {2, 4, 6} : P(6 | pair) = 1/3." },
  { d: 4, o: "4.2", q: "Une urne contient 4 boules rouges et 6 blanches. On tire successivement deux boules sans remise. Quelle est la probabilité d’obtenir deux boules rouges ?", a: ["4/25", "2/15", "1/5", "7/15"], c: 1, e: "Probabilité d’une intersection : P(R₁ ∩ R₂) = P(R₁) × P(R₂|R₁) = 4/10 × 3/9 = 12/90 = 2/15. 4/25 correspondrait à un tirage avec remise." },
  { d: 4, o: "4.2", q: "Dans un hôpital, 30 % des patients sont hospitalisés en chirurgie, et 10 % d’entre eux contractent une infection nosocomiale. Quelle proportion des patients de l’hôpital est en chirurgie et infectée ?", a: ["3 %", "10 %", "40 %", "33 %"], c: 0, e: "P(C ∩ I) = P(C) × P(I|C) = 0,30 × 0,10 = 0,03, soit 3 %." },
  { d: 4, o: "4.2", q: "À quelle condition la probabilité conditionnelle P(A|B) est-elle définie ?", a: ["P(B) > 0", "P(A) > 0", "A et B indépendants", "A et B incompatibles"], c: 0, e: "P(A|B) = P(A ∩ B) / P(B) exige de ne pas diviser par 0 : il faut P(B) > 0." },
  { d: 4, o: "4.2", q: "Pour deux événements A et B de probabilités non nulles, quelles égalités sont vraies ? (Choisissez 2 réponses)", a: ["P(A ∩ B) = P(B) × P(A|B)", "P(A ∩ B) = P(A) × P(B|A)", "P(A|B) = P(B|A)", "P(A|B) = P(A ∩ B) × P(B)", "P(A|B) + P(A|B̄) = 1"], c: [0, 1], e: "La probabilité d’une intersection s’écrit P(B)P(A|B) = P(A)P(B|A). En général P(A|B) ≠ P(B|A), et c’est P(A|B) + P(Ā|B) qui vaut 1." },
  { d: 4, o: "4.2", q: "Parmi 1000 donneurs de sang, 450 sont du groupe O, dont 380 de rhésus positif. Quelle est la probabilité qu’un donneur soit rhésus positif sachant qu’il est du groupe O ?", a: ["Environ 0,84", "0,38", "0,45", "Environ 0,16"], c: 0, e: "P(Rh+ | O) = 380 / 450 ≈ 0,84. 0,38 = 380/1000 est la probabilité de l’intersection." },
  { d: 4, o: "4.2", q: "Dans une maternité, 60 % des accouchées ont moins de 30 ans et 15 % ont moins de 30 ans et un premier enfant. Quelle est la probabilité qu’une accouchée ait son premier enfant sachant qu’elle a moins de 30 ans ?", a: ["0,25", "0,15", "0,09", "0,6"], c: 0, e: "P(premier enfant | moins de 30 ans) = P(les deux) / P(moins de 30 ans) = 0,15 / 0,60 = 0,25. Multiplier 0,15 × 0,6 = 0,09 n’a pas de sens ici." },

  // 4.3 Indépendance
  { d: 4, o: "4.3", q: "A et B sont indépendants, avec P(A) = 0,4 et P(B) = 0,5. Que vaut P(A ∩ B) ?", a: ["0,2", "0,9", "0,1", "0,45"], c: 0, e: "Définition de l’indépendance : P(A ∩ B) = P(A) × P(B) = 0,4 × 0,5 = 0,2." },
  { d: 4, o: "4.3", q: "On a P(A) = 0,3, P(B) = 0,2 et P(A ∩ B) = 0,06. Les événements A et B sont-ils indépendants ?", a: ["Oui, car P(A ∩ B) = P(A) × P(B)", "Non, car P(A ∩ B) ≠ 0", "Non, car ils ne sont pas incompatibles", "On ne peut pas conclure"], c: 0, e: "0,3 × 0,2 = 0,06 = P(A ∩ B) : A et B sont indépendants. Le fait que l’intersection soit non vide ne s’oppose pas à l’indépendance." },
  { d: 4, o: "4.3", q: "A et B sont incompatibles, avec P(A) = 0,3 et P(B) = 0,4. Sont-ils indépendants ?", a: ["Oui, toujours", "Non, car P(A ∩ B) = 0 alors que P(A) × P(B) = 0,12", "Oui, car P(A ∩ B) = 0", "On ne peut pas conclure"], c: 1, e: "Indépendants vs incompatibles : deux événements incompatibles de probabilités non nulles ne sont jamais indépendants, car la réalisation de l’un rend l’autre impossible." },
  { d: 4, o: "4.3", q: "Trois patients reçoivent un traitement ; chacun présente, indépendamment des autres, un effet indésirable avec une probabilité de 0,1. Quelle est la probabilité qu’au moins un patient présente un effet indésirable ?", a: ["0,271", "0,3", "0,001", "0,729"], c: 0, e: "P(aucun) = 0,9³ = 0,729 grâce à l’indépendance, donc P(au moins un) = 1 − 0,729 = 0,271. Additionner 3 × 0,1 surestime le résultat." },
  { d: 4, o: "4.3", q: "Si P(A|B) = P(A), avec P(B) > 0, que peut-on en conclure ?", a: ["A et B sont indépendants", "A et B sont incompatibles", "A est inclus dans B", "P(B) = 1"], c: 0, e: "P(A|B) = P(A) signifie que savoir B réalisé ne modifie pas la probabilité de A : c’est une définition équivalente de l’indépendance." },
  { d: 4, o: "4.3", q: "A et B sont indépendants, avec P(A) = 0,3 et P(B) = 0,6. Que vaut P(Ā ∩ B̄) ?", a: ["0,28", "0,1", "0,72", "0,18"], c: 0, e: "Si A et B sont indépendants, Ā et B̄ le sont aussi : P(Ā ∩ B̄) = 0,7 × 0,4 = 0,28." },
  { d: 4, o: "4.3", q: "A et B sont indépendants, avec P(A) = 0,3 et P(B) = 0,6. Que vaut P(A ∪ B) ?", a: ["0,9", "0,72", "0,18", "0,82"], c: 1, e: "P(A ∩ B) = 0,3 × 0,6 = 0,18, donc P(A ∪ B) = 0,3 + 0,6 − 0,18 = 0,72." },
  { d: 4, o: "4.3", q: "Deux tests de dépistage indépendants ont chacun un taux de faux positifs de 5 %. Quelle est la probabilité qu’un sujet sain soit positif aux deux tests ?", a: ["0,0025", "0,1", "0,05", "0,025"], c: 0, e: "Les tests étant indépendants, on multiplie : 0,05 × 0,05 = 0,0025." },
  { d: 4, o: "4.3", q: "On lance deux dés équilibrés indépendants. Quelle est la probabilité d’obtenir un double six ?", a: ["1/6", "1/12", "1/36", "1/3"], c: 2, e: "Les lancers sont indépendants : 1/6 × 1/6 = 1/36." },
  { d: 4, o: "4.3", q: "Dans un échantillon de 100 personnes, 40 présentent le caractère A, 30 le caractère B et 12 les deux. Que peut-on en dire ?", a: ["A et B sont indépendants", "A et B sont incompatibles", "A et B sont dépendants, car 12 ≠ 0", "P(A|B) = 0,12"], c: 0, e: "P(A) × P(B) = 0,4 × 0,3 = 0,12 = P(A ∩ B) : A et B sont indépendants. On le vérifie aussi avec P(A|B) = 12/30 = 0,4 = P(A)." },
  { d: 4, o: "4.3", q: "On a P(A) = 0,3 et P(A|B) = 0,5. Les événements A et B sont-ils indépendants ?", a: ["Oui", "Non, car P(A|B) ≠ P(A)", "Oui, car P(A|B) > P(A)", "On ne peut pas conclure sans P(B)"], c: 1, e: "Indépendance ⇔ P(A|B) = P(A). Ici, savoir B réalisé fait passer la probabilité de A de 0,3 à 0,5 : ils sont dépendants." },
  { d: 4, o: "4.3", q: "A et B sont indépendants, avec P(A) = 0,5 et P(B) = 0,2. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["P(A ∩ B) = 0,1", "P(A|B) = 0,5", "A et B sont incompatibles", "P(A ∪ B) = 0,7", "P(B|A) = 0,1"], c: [0, 1], e: "P(A ∩ B) = 0,5 × 0,2 = 0,1 et P(A|B) = P(A) = 0,5. P(A ∪ B) = 0,5 + 0,2 − 0,1 = 0,6, et P(B|A) = P(B) = 0,2." },

  // 4.4 Arbres
  { d: 4, o: "4.4", q: "Une maladie a une prévalence de 10 %. Un test est positif chez 80 % des malades et chez 10 % des non-malades. Quelle est la probabilité qu’un test soit positif ?", a: ["0,17", "0,9", "0,08", "0,26"], c: 0, e: "Formule des probabilités totales : P(T+) = 0,1 × 0,8 + 0,9 × 0,1 = 0,08 + 0,09 = 0,17." },
  { d: 4, o: "4.4", q: "Dans un arbre pondéré, que vaut la somme des probabilités portées par les branches issues d’un même nœud ?", a: ["1", "0", "La probabilité du nœud", "Cela dépend de l’arbre"], c: 0, e: "Les branches issues d’un nœud représentent toutes les possibilités à cette étape : leurs probabilités (conditionnelles) somment à 1." },
  { d: 4, o: "4.4", q: "Dans un arbre pondéré, P(B) = 0,3 et P(A|B) = 0,4. Quelle est la probabilité du chemin « B puis A » ?", a: ["0,12", "0,7", "0,4", "0,3"], c: 0, e: "La probabilité d’un chemin est le produit des probabilités de ses branches : P(B ∩ A) = 0,3 × 0,4 = 0,12." },
  { d: 4, o: "4.4", q: "Un hôpital achète 60 % de ses seringues au laboratoire L1 et 40 % au laboratoire L2. Les taux de défaut sont de 2 % pour L1 et 5 % pour L2. Quelle est la probabilité qu’une seringue soit défectueuse ?", a: ["3,2 %", "3,5 %", "7 %", "2 %"], c: 0, e: "P(D) = 0,6 × 0,02 + 0,4 × 0,05 = 0,012 + 0,020 = 0,032. La moyenne simple 3,5 % ne tient pas compte des proportions de chaque laboratoire." },
  { d: 4, o: "4.4", q: "Les patients d’un hôpital se répartissent en trois services : A (50 %), B (30 %) et C (20 %). Le taux d’infection vaut 2 % en A, 4 % en B et 10 % en C. Quelle est la probabilité qu’un patient soit infecté ?", a: ["4,2 %", "5,3 %", "16 %", "3,3 %"], c: 0, e: "Partition en trois services : P(I) = 0,5 × 0,02 + 0,3 × 0,04 + 0,2 × 0,10 = 0,010 + 0,012 + 0,020 = 0,042." },
  { d: 4, o: "4.4", q: "Dans une population, 70 % des personnes sont vaccinées. La probabilité de tomber malade est de 2 % chez les vaccinés et de 20 % chez les non-vaccinés. Quelle est la probabilité qu’une personne tombe malade ?", a: ["7,4 %", "22 %", "11 %", "1,4 %"], c: 0, e: "P(M) = 0,7 × 0,02 + 0,3 × 0,20 = 0,014 + 0,060 = 0,074." },
  { d: 4, o: "4.4", q: "Dans un arbre pondéré, P(B) = 0,4, P(A|B) = 0,25 et P(A|B̄) = 0,5. Que vaut P(A) ?", a: ["0,4", "0,75", "0,125", "0,1"], c: 0, e: "P(A) = 0,4 × 0,25 + 0,6 × 0,5 = 0,1 + 0,3 = 0,4. Il faut additionner tous les chemins qui mènent à A." },
  { d: 4, o: "4.4", q: "Lorsque B et B̄ forment une partition de l’univers, que dit la formule des probabilités totales ?", a: ["P(A) = P(B)·P(A|B) + P(B̄)·P(A|B̄)", "P(A) = P(A|B) + P(A|B̄)", "P(A) = P(B)·P(A|B) × P(B̄)·P(A|B̄)", "P(A) = P(A ∩ B) − P(A ∩ B̄)"], c: 0, e: "On additionne les probabilités des deux chemins qui mènent à A : P(A ∩ B) + P(A ∩ B̄). Additionner seulement les probabilités conditionnelles oublie de les pondérer." },
  { d: 4, o: "4.4", q: "Pour appliquer la formule des probabilités totales avec les événements B₁, B₂, B₃, quelle condition faut-il vérifier ?", a: ["B₁, B₂, B₃ forment une partition de l’univers : deux à deux incompatibles et de réunion Ω", "B₁, B₂, B₃ sont indépendants", "B₁, B₂, B₃ ont la même probabilité", "P(A) = 1"], c: 0, e: "La formule découpe A selon des cas qui ne se chevauchent pas et couvrent toutes les possibilités : c’est une partition." },
  { d: 4, o: "4.4", q: "On lance une pièce : pile, on tire dans l’urne U₁ (3 rouges, 2 blanches) ; face, dans l’urne U₂ (1 rouge, 4 blanches). Quelle est la probabilité de tirer une boule rouge ?", a: ["0,4", "0,8", "0,3", "0,5"], c: 0, e: "Arbre pondéré : P(R) = 0,5 × 3/5 + 0,5 × 1/5 = 0,3 + 0,1 = 0,4." },
  { d: 4, o: "4.4", q: "Dans un arbre pondéré, P(B) = 0,2 et P(A|B̄) = 0,15. Quelle est la probabilité du chemin « B̄ puis A » ?", a: ["0,12", "0,03", "0,15", "0,35"], c: 0, e: "P(B̄) = 1 − 0,2 = 0,8, donc P(B̄ ∩ A) = 0,8 × 0,15 = 0,12. Utiliser P(B) au lieu de P(B̄) donne 0,03." },
  { d: 4, o: "4.4", q: "Un test est positif chez 95 % des malades et chez 10 % des non-malades ; la prévalence est de 20 %. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["P(M ∩ T+) = 0,19", "P(T+) = 0,27", "P(T+) = 1,05", "P(M̄ ∩ T+) = 0,10", "P(T+) = 0,19"], c: [0, 1], e: "P(M ∩ T+) = 0,2 × 0,95 = 0,19 et P(M̄ ∩ T+) = 0,8 × 0,10 = 0,08. Formule des probabilités totales : P(T+) = 0,19 + 0,08 = 0,27." },

  // 4.5 Formule de Bayes
  { d: 4, o: "4.5", q: "Une maladie a une prévalence de 1 %. Un test est positif chez 99 % des malades et chez 5 % des non-malades. Quelle est la probabilité qu’une personne testée positive soit malade ?", a: ["Environ 17 %", "99 %", "95 %", "1 %"], c: 0, e: "Formule de Bayes : P(M|T+) = 0,01 × 0,99 / (0,01 × 0,99 + 0,99 × 0,05) = 0,0099 / 0,0594 ≈ 0,17. Quand la maladie est rare, la plupart des positifs sont des faux positifs." },
  { d: 4, o: "4.5", q: "On sait que P(A|B) = 0,8, P(B) = 0,1 et P(A) = 0,2. Que vaut P(B|A) ?", a: ["0,4", "0,8", "0,016", "0,25"], c: 0, e: "Formule de Bayes : P(B|A) = P(A|B) × P(B) / P(A) = 0,8 × 0,1 / 0,2 = 0,4." },
  { d: 4, o: "4.5", q: "Un hôpital achète 60 % de ses seringues à L1 (2 % de défaut) et 40 % à L2 (5 % de défaut). Une seringue est défectueuse. Quelle est la probabilité qu’elle vienne de L2 ?", a: ["62,5 %", "40 %", "5 %", "2 %"], c: 0, e: "P(D) = 0,012 + 0,020 = 0,032. Par inversion du conditionnement, P(L2|D) = 0,020 / 0,032 = 0,625." },
  { d: 4, o: "4.5", q: "70 % d’une population est vaccinée. Le risque de maladie est de 2 % chez les vaccinés et de 20 % chez les non-vaccinés. Quelle proportion des malades est vaccinée ?", a: ["Environ 19 %", "70 %", "2 %", "1,4 %"], c: 0, e: "P(M) = 0,014 + 0,060 = 0,074, puis P(V|M) = 0,014 / 0,074 ≈ 0,19. Environ un malade sur cinq est vacciné, même si le vaccin divise le risque par 10." },
  { d: 4, o: "4.5", q: "Un patient reçoit un résultat de test positif. Quelle probabilité l’intéresse pour savoir s’il est malade ?", a: ["P(M|T+)", "P(T+|M)", "P(T+)", "P(M ∩ T+)"], c: 0, e: "Le patient veut connaître la probabilité d’être malade sachant que son test est positif : P(M|T+). P(T+|M) décrit la qualité du test chez les malades." },
  { d: 4, o: "4.5", q: "À qualités de test égales, comment évolue la probabilité d’être malade sachant que le test est positif, P(M|T+), quand la prévalence de la maladie diminue ?", a: ["Elle diminue", "Elle augmente", "Elle ne change pas", "Elle devient égale à la sensibilité"], c: 0, e: "D’après la formule de Bayes, le numérateur P(M)P(T+|M) diminue plus vite que le dénominateur : plus la maladie est rare, plus la part de faux positifs parmi les positifs est grande." },
  { d: 4, o: "4.5", q: "Sur un effectif fictif de 10 000 personnes, la prévalence est de 2 %, le test est positif chez 90 % des malades et chez 10 % des non-malades. Quelle est la probabilité d’être malade si le test est positif ?", a: ["Environ 15,5 %", "90 %", "18 %", "2 %"], c: 0, e: "200 malades donnent 180 positifs ; 9 800 non-malades donnent 980 positifs. P(M|T+) = 180 / (180 + 980) = 180 / 1160 ≈ 0,155." },
  { d: 4, o: "4.5", q: "On lance une pièce : pile, on tire dans U₁ (3 rouges, 2 blanches) ; face, dans U₂ (1 rouge, 4 blanches). La boule tirée est rouge. Quelle est la probabilité que la pièce soit tombée sur pile ?", a: ["0,75", "0,6", "0,5", "0,3"], c: 0, e: "P(R) = 0,3 + 0,1 = 0,4 et P(pile ∩ R) = 0,5 × 0,6 = 0,3. Par Bayes : P(pile|R) = 0,3 / 0,4 = 0,75." },
  { d: 4, o: "4.5", q: "Un étudiant affirme : « le test est positif chez 95 % des malades, donc un patient positif a 95 % de chances d’être malade ». Quelle est son erreur ?", a: ["Il confond P(T+|M) et P(M|T+)", "Il oublie que 95 % n’est pas une probabilité", "Il confond sensibilité et prévalence", "Il n’y a pas d’erreur"], c: 0, e: "C’est l’erreur d’inversion du conditionnement. P(M|T+) dépend aussi de la prévalence et du taux de faux positifs, via la formule de Bayes." },
  { d: 4, o: "4.5", q: "Trois services : A (50 % des patients, 2 % d’infection), B (30 %, 4 %) et C (20 %, 10 %). Un patient est infecté. Quelle est la probabilité qu’il soit hospitalisé en C ?", a: ["Environ 48 %", "20 %", "10 %", "33 %"], c: 0, e: "P(I) = 0,010 + 0,012 + 0,020 = 0,042 et P(C ∩ I) = 0,020. P(C|I) = 0,020 / 0,042 ≈ 0,48." },
  { d: 4, o: "4.5", q: "Quelle est l’écriture de la formule de Bayes ?", a: ["P(B|A) = P(A|B) × P(B) / P(A)", "P(B|A) = P(A|B) × P(A) / P(B)", "P(B|A) = P(A|B) × P(A) × P(B)", "P(B|A) = 1 − P(A|B)"], c: 0, e: "P(B|A) = P(A ∩ B) / P(A), et P(A ∩ B) = P(A|B) × P(B)." },
  { d: 4, o: "4.5", q: "Dans l’expression P(M|T+) = P(M)P(T+|M) / D, à quoi est égal le dénominateur D ?", a: ["P(M)P(T+|M) + P(M̄)P(T+|M̄)", "P(M)P(T+|M) + P(M̄)P(T−|M̄)", "P(T+|M) + P(T+|M̄)", "P(M) + P(T+)"], c: 0, e: "D = P(T+), calculée par la formule des probabilités totales. On additionne les vrais positifs et les faux positifs." },
  { d: 4, o: "4.5", q: "La prévalence d’une maladie est de 10 %, avec P(T+|M) = 0,9 et P(T+|M̄) = 0,1. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["P(T+) = 0,18", "P(M|T+) = 0,5", "P(M|T+) = 0,9", "P(M|T+) = 0,09", "P(T+) = 0,9"], c: [0, 1], e: "P(T+) = 0,1 × 0,9 + 0,9 × 0,1 = 0,18. P(M|T+) = 0,09 / 0,18 = 0,5 : un positif sur deux seulement est malade." },
  { d: 4, o: "4.5", q: "La prévalence d’une maladie est de 10 %, avec P(T+|M) = 0,9 et P(T+|M̄) = 0,1. Quelle est la probabilité d’être malade sachant que le test est négatif ?", a: ["Environ 1,2 %", "10 %", "0,1 %", "11 %"], c: 0, e: "P(T−|M) = 0,1 et P(T−|M̄) = 0,9. P(T−) = 0,01 + 0,81 = 0,82, donc P(M|T−) = 0,01 / 0,82 ≈ 0,012." },

  // ── Domaine 5 : Variables aléatoires et lois de probabilité ──────────────
  // 5.1 Espérance
  { d: 5, o: "5.1", q: "Une variable aléatoire X prend les valeurs 1, 2 et 3 avec les probabilités 0,2 ; 0,5 et 0,3. Que vaut son espérance ?", a: ["2", "2,1", "1", "6"], c: 1, e: "E(X) = Σ xᵢpᵢ = 1 × 0,2 + 2 × 0,5 + 3 × 0,3 = 0,2 + 1 + 0,9 = 2,1." },
  { d: 5, o: "5.1", q: "La loi d’une variable aléatoire discrète X est : P(X = 0) = 0,1 ; P(X = 1) = 0,4 ; P(X = 2) = 0,3 ; P(X = 3) = p. Que vaut p ?", a: ["0,2", "0,3", "0,8", "0,25"], c: 0, e: "La somme des probabilités d’une loi vaut 1 : p = 1 − (0,1 + 0,4 + 0,3) = 0,2." },
  { d: 5, o: "5.1", q: "Une variable aléatoire X a pour espérance E(X) = 5. Que vaut E(3X − 2) ?", a: ["13", "15", "3", "11"], c: 0, e: "Linéarité de l’espérance : E(3X − 2) = 3E(X) − 2 = 15 − 2 = 13." },
  { d: 5, o: "5.1", q: "Deux variables aléatoires vérifient E(X) = 2 et E(Y) = 3. Que vaut E(X + Y) ?", a: ["5", "6", "2,5", "On ne peut pas conclure sans savoir si X et Y sont indépendantes"], c: 0, e: "E(X + Y) = E(X) + E(Y) = 5, toujours, que X et Y soient indépendantes ou non." },
  { d: 5, o: "5.1", q: "Un jeu coûte 2 € ; on gagne 10 € avec une probabilité de 0,1 et rien sinon. Quelle est l’espérance du gain net ?", a: ["−1 €", "1 €", "0,8 €", "0 €"], c: 0, e: "Gain net : +8 € avec probabilité 0,1 et −2 € avec probabilité 0,9. E = 0,8 − 1,8 = −1 € : en moyenne, on perd 1 € par partie." },
  { d: 5, o: "5.1", q: "Que représente l’espérance E(X) d’une variable aléatoire ?", a: ["La moyenne des valeurs de X sur un grand nombre de répétitions", "La valeur la plus probable de X", "La valeur qui partage la loi en deux moitiés", "La plus grande valeur que X peut prendre"], c: 0, e: "L’espérance est une moyenne théorique pondérée par les probabilités. Elle n’est pas forcément une valeur que X peut prendre, ni la plus probable." },
  { d: 5, o: "5.1", q: "X prend les valeurs −1, 0 et 2 avec les probabilités 0,3 ; 0,5 et 0,2. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["E(X) = 0,1", "E(10X) = 1", "E(X) = 1/3", "E(X + 1) = 0,1", "E(X) = 0,5"], c: [0, 1], e: "E(X) = −0,3 + 0 + 0,4 = 0,1. Par linéarité, E(10X) = 1 et E(X + 1) = 1,1. La moyenne simple des valeurs (1/3) ne tient pas compte des probabilités." },

  // 5.2 Variance
  { d: 5, o: "5.2", q: "X vaut 0 ou 2, chacune avec une probabilité de 0,5. Quelle est la variance de X ?", a: ["1", "2", "0", "4"], c: 0, e: "E(X) = 1 et E(X²) = 0,5 × 0 + 0,5 × 4 = 2. V(X) = E(X²) − [E(X)]² = 2 − 1 = 1." },
  { d: 5, o: "5.2", q: "Une variable aléatoire X a une variance V(X) = 4. Que vaut V(3X + 5) ?", a: ["36", "17", "12", "41"], c: 0, e: "V(aX + b) = a²V(X) = 9 × 4 = 36. La constante 5 ne modifie pas la dispersion." },
  { d: 5, o: "5.2", q: "Une variable aléatoire X a une variance V(X) = 2,5. Que vaut V(X + 10) ?", a: ["2,5", "12,5", "25", "102,5"], c: 0, e: "Ajouter une constante décale toutes les valeurs sans changer leur dispersion : V(X + 10) = V(X) = 2,5." },
  { d: 5, o: "5.2", q: "On sait que E(X) = 3 et E(X²) = 13. Quelle est la variance de X ?", a: ["4", "10", "16", "2"], c: 0, e: "V(X) = E(X²) − [E(X)]² = 13 − 9 = 4. 2 est l’écart-type, pas la variance." },
  { d: 5, o: "5.2", q: "La variance d’une variable aléatoire peut-elle être négative ?", a: ["Non, elle est toujours positive ou nulle, et nulle seulement si X est constante", "Oui, si X prend des valeurs négatives", "Oui, si E(X) est négative", "Oui, si X est centrée"], c: 0, e: "La variance d’une variable aléatoire est une moyenne de carrés (X − E(X))², donc toujours ≥ 0." },
  { d: 5, o: "5.2", q: "Une variable aléatoire X a une variance V(X) = 3. Que vaut V(−2X) ?", a: ["12", "−6", "−12", "6"], c: 0, e: "V(aX) = a²V(X) = (−2)² × 3 = 12. Le signe de a disparaît car il est élevé au carré." },

  // 5.3 Écart-type
  { d: 5, o: "5.3", q: "Une variable aléatoire a une variance de 16. Quel est son écart-type ?", a: ["4", "16", "8", "256"], c: 0, e: "Écart-type d’une variable aléatoire : σ = √V = √16 = 4." },
  { d: 5, o: "5.3", q: "Une variable aléatoire X a un écart-type σ(X) = 3. Que vaut σ(2X + 7) ?", a: ["6", "13", "12", "36"], c: 0, e: "σ(aX + b) = |a|·σ(X) = 2 × 3 = 6. La constante 7 n’intervient pas." },
  { d: 5, o: "5.3", q: "X est une dose exprimée en mg. Dans quelle unité s’expriment son écart-type et sa variance ?", a: ["Écart-type en mg, variance en mg²", "Écart-type en mg², variance en mg", "Tous deux en mg", "Tous deux sans unité"], c: 0, e: "La variance est une moyenne de carrés d’écarts (mg²) ; l’écart-type, sa racine carrée, revient à l’unité de X." },
  { d: 5, o: "5.3", q: "Deux traitements donnent la même baisse moyenne de tension, avec des écarts-types de 2 mmHg et 8 mmHg. Comment interpréter cette différence ?", a: ["Les résultats du second traitement sont plus dispersés autour de la moyenne", "Le second traitement est quatre fois plus efficace", "Le premier traitement est inefficace", "Les deux traitements ont la même dispersion"], c: 0, e: "Interprétation de l’écart-type : il mesure la dispersion autour de l’espérance. Même moyenne, mais réponses beaucoup plus variables d’un patient à l’autre avec le second traitement." },
  { d: 5, o: "5.3", q: "Une variable aléatoire X a pour espérance 10 et pour variance 9. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["σ(X) = 3", "σ(−X) = 3", "σ(X) = 81", "σ(−X) = −3", "σ(X + 5) = 8"], c: [0, 1], e: "σ(X) = √9 = 3, et σ(aX + b) = |a|σ(X), donc σ(−X) = 3 et σ(X + 5) = 3. Un écart-type n’est jamais négatif." },

  // 5.4 Loi binomiale
  { d: 5, o: "5.4", q: "X suit la loi binomiale B(4 ; 0,5). Que vaut P(X = 2) ?", a: ["0,375", "0,5", "0,25", "0,0625"], c: 0, e: "P(X = k) = C(n, k)pᵏ(1 − p)ⁿ⁻ᵏ : C(4, 2) × 0,5² × 0,5² = 6 × 1/16 = 0,375. Oublier le coefficient C(4, 2) = 6 donne 0,0625." },
  { d: 5, o: "5.4", q: "X suit la loi binomiale B(50 ; 0,2). Quelles sont son espérance et sa variance ?", a: ["E(X) = 10 et V(X) = 8", "E(X) = 10 et V(X) = 10", "E(X) = 0,2 et V(X) = 0,16", "E(X) = 10 et V(X) = 2"], c: 0, e: "Espérance np = 50 × 0,2 = 10 ; variance np(1 − p) = 10 × 0,8 = 8." },
  { d: 5, o: "5.4", q: "Chacun de 5 patients développe une allergie, indépendamment des autres, avec une probabilité de 0,1. Quelle est la probabilité qu’au moins un patient développe une allergie ?", a: ["Environ 0,41", "0,5", "Environ 0,59", "0,1"], c: 0, e: "X ~ B(5 ; 0,1) et P(X ≥ 1) = 1 − P(X = 0) = 1 − 0,9⁵ ≈ 1 − 0,590 = 0,41." },
  { d: 5, o: "5.4", q: "Que vaut le coefficient binomial C(5, 2) ?", a: ["10", "20", "5", "25"], c: 0, e: "C(5, 2) = 5! / (2! × 3!) = 120 / (2 × 6) = 10 : il y a 10 façons de placer 2 succès parmi 5 épreuves." },
  { d: 5, o: "5.4", q: "Laquelle de ces situations NE relève PAS d’une loi binomiale ?", a: ["Tirer 5 boules sans remise dans une urne de 10 boules et compter les rouges", "Lancer 10 fois une pièce et compter les piles", "Traiter 20 patients indépendants, chacun guérissant avec une probabilité de 0,7, et compter les guérisons", "Tirer 5 boules avec remise et compter les rouges"], c: 0, e: "Sans remise dans une petite urne, la probabilité de succès change d’un tirage à l’autre et les tirages ne sont pas indépendants : ce n’est pas un schéma de Bernoulli." },
  { d: 5, o: "5.4", q: "Qu’est-ce qu’une épreuve de Bernoulli ?", a: ["Une expérience aléatoire à deux issues : succès avec probabilité p, échec avec probabilité 1 − p", "Une expérience répétée n fois", "Une expérience dont toutes les issues sont équiprobables", "Une expérience dont le résultat suit une loi normale"], c: 0, e: "L’épreuve de Bernoulli est l’épreuve élémentaire à deux issues. La loi binomiale compte les succès sur n épreuves de Bernoulli identiques et indépendantes." },
  { d: 5, o: "5.4", q: "X suit la loi binomiale B(10 ; 0,4). Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["E(X) = 4", "V(X) = 2,4", "V(X) = 4", "P(X = 0) = 0,4¹⁰", "X peut prendre la valeur 11"], c: [0, 1], e: "E(X) = 10 × 0,4 = 4 et V(X) = 4 × 0,6 = 2,4. P(X = 0) = 0,6¹⁰ (aucun succès), et X prend ses valeurs entre 0 et 10." },

  // 5.5 Loi normale
  { d: 5, o: "5.5", q: "La taille X des adultes d’une population suit la loi normale N(170, 8²) (en cm). Que vaut P(X ≤ 170) ?", a: ["0,5", "0,68", "0,95", "0"], c: 0, e: "La loi normale est symétrique autour de sa moyenne μ = 170 : la moitié des valeurs est inférieure à μ." },
  { d: 5, o: "5.5", q: "X suit la loi N(120, 15²). Quelle valeur de la variable centrée réduite Z correspond à X = 150 ?", a: ["2", "30", "0,5", "1,25"], c: 0, e: "Centrage et réduction : Z = (X − μ) / σ = (150 − 120) / 15 = 2." },
  { d: 5, o: "5.5", q: "La taille de femmes adultes suit une loi normale de moyenne 165 cm et d’écart-type 6 cm. Quelle proportion approximative mesure entre 153 et 177 cm ?", a: ["95 %", "68 %", "99,7 %", "50 %"], c: 0, e: "153 et 177 correspondent à μ ± 2σ. D’après la règle 68-95-99,7, environ 95 % des valeurs sont dans cet intervalle." },
  { d: 5, o: "5.5", q: "Z suit la loi normale centrée réduite. Que vaut P(Z ≤ 1,96) ?", a: ["0,975", "0,95", "0,025", "0,05"], c: 0, e: "P(−1,96 ≤ Z ≤ 1,96) = 0,95, et il reste 2,5 % de chaque côté. Donc P(Z ≤ 1,96) = 0,95 + 0,025 = 0,975." },
  { d: 5, o: "5.5", q: "Z suit la loi normale centrée réduite et P(Z ≤ 1) ≈ 0,841. Que vaut P(Z ≤ −1) ?", a: ["Environ 0,159", "Environ 0,841", "Environ −0,841", "0,5"], c: 0, e: "Par symétrie, Φ(−z) = 1 − Φ(z) : P(Z ≤ −1) = 1 − 0,841 = 0,159." },
  { d: 5, o: "5.5", q: "X suit une loi normale de moyenne 170. Que vaut P(X = 170) ?", a: ["0", "0,5", "La valeur maximale de la densité", "1"], c: 0, e: "Pour une loi continue comme la loi normale, la probabilité d’une valeur isolée est nulle : on calcule des probabilités d’intervalles." },
  { d: 5, o: "5.5", q: "X suit la loi N(100, 10²). Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["P(80 ≤ X ≤ 120) ≈ 0,95", "P(X ≥ 100) = 0,5", "P(90 ≤ X ≤ 110) ≈ 0,95", "P(X ≥ 130) ≈ 0,5", "La médiane de X vaut 110"], c: [0, 1], e: "[80 ; 120] = μ ± 2σ contient environ 95 % des valeurs, et [90 ; 110] = μ ± σ environ 68 %. Par symétrie, P(X ≥ μ) = 0,5 et la médiane vaut μ = 100 ; P(X ≥ 130) ≈ 0,15 %." },

  // ── Domaine 6 : Statistiques descriptives ───────────────────────────────
  // 6.1 Moyenne
  { d: 6, o: "6.1", q: "Quelle est la moyenne arithmétique de la série 12, 15, 9, 14 ?", a: ["12", "12,5", "14", "50"], c: 1, e: "x̄ = (12 + 15 + 9 + 14) / 4 = 50 / 4 = 12,5." },
  { d: 6, o: "6.1", q: "Un étudiant obtient 12 à une épreuve de coefficient 2 et 15 à une épreuve de coefficient 3. Quelle est sa moyenne pondérée ?", a: ["13,5", "13,8", "14", "69"], c: 1, e: "Moyenne pondérée : (12 × 2 + 15 × 3) / (2 + 3) = (24 + 45) / 5 = 13,8. La moyenne simple 13,5 ignore les coefficients." },
  { d: 6, o: "6.1", q: "Sur 20 familles, 5 n’ont aucun enfant, 8 en ont 1, 5 en ont 2 et 2 en ont 3. Quel est le nombre moyen d’enfants par famille ?", a: ["1,2", "1,5", "6", "2"], c: 0, e: "x̄ = Σ nᵢxᵢ / Σ nᵢ = (0 × 5 + 1 × 8 + 2 × 5 + 3 × 2) / 20 = 24 / 20 = 1,2." },
  { d: 6, o: "6.1", q: "La moyenne de la série 10, 12, 14 vaut 12. On ajoute la valeur 44. Quelle est la nouvelle moyenne ?", a: ["12", "13", "20", "26"], c: 2, e: "(10 + 12 + 14 + 44) / 4 = 80 / 4 = 20. Une seule valeur extrême suffit à déplacer fortement la moyenne." },
  { d: 6, o: "6.1", q: "Un groupe A de 20 patients a un poids moyen de 70 kg, un groupe B de 30 patients un poids moyen de 60 kg. Quel est le poids moyen de l’ensemble des 50 patients ?", a: ["65 kg", "64 kg", "62 kg", "130 kg"], c: 1, e: "Il faut pondérer par les effectifs : (20 × 70 + 30 × 60) / 50 = (1400 + 1800) / 50 = 64 kg. La moyenne des moyennes (65 kg) est fausse quand les effectifs diffèrent." },
  { d: 6, o: "6.1", q: "Une série statistique a une moyenne de 20. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["Si l’on ajoute 5 à chaque valeur, la moyenne devient 25", "Si l’on multiplie chaque valeur par 2, la moyenne devient 40", "Si l’on ajoute 5 à chaque valeur, la moyenne reste 20", "La moyenne est forcément une des valeurs de la série", "La moyenne est insensible aux valeurs extrêmes"], c: [0, 1], e: "La moyenne arithmétique suit les transformations affines : +5 sur chaque valeur ajoute 5, ×2 multiplie par 2. Elle n’est pas forcément une valeur de la série et elle est sensible aux valeurs extrêmes." },

  // 6.2 Médiane
  { d: 6, o: "6.2", q: "Quelle est la médiane de la série 7, 3, 12, 1, 5 ?", a: ["5", "12", "5,6", "1"], c: 0, e: "Calcul de la médiane : on ordonne la série (1, 3, 5, 7, 12) ; n = 5 est impair, la médiane est la 3ᵉ valeur, soit 5. 5,6 est la moyenne." },
  { d: 6, o: "6.2", q: "Quelle est la médiane de la série 4, 8, 10, 15, 20, 30 ?", a: ["10", "12,5", "15", "14,5"], c: 1, e: "n = 6 est pair : la médiane est la moyenne des deux valeurs centrales, (10 + 15) / 2 = 12,5. 14,5 est la moyenne de la série." },
  { d: 6, o: "6.2", q: "Les durées de séjour de 5 patients sont 2, 3, 3, 4 et 45 jours. Quel indicateur décrit le mieux la durée de séjour typique ?", a: ["La médiane", "La moyenne", "La valeur maximale", "L’étendue"], c: 0, e: "La moyenne (11,4 jours) est tirée vers le haut par la valeur 45. La médiane (3 jours) est robuste aux valeurs extrêmes." },
  { d: 6, o: "6.2", q: "Dans la série 2, 5, 7, 9, 11, on remplace 11 par 110. Que devient la médiane ?", a: ["Elle reste égale à 7", "Elle devient 26,6", "Elle devient 9", "Elle devient 57,5"], c: 0, e: "La valeur centrale de la série ordonnée reste 7 : c’est la robustesse aux valeurs extrêmes de la médiane. La moyenne, elle, passe de 6,8 à 26,6." },
  { d: 6, o: "6.2", q: "On considère la série 1, 2, 2, 3, 4, 6, 10, 12. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["La médiane vaut 3,5", "La moyenne vaut 5", "La médiane vaut 4", "La moyenne vaut 3,5", "La médiane est supérieure à la moyenne"], c: [0, 1], e: "n = 8 : médiane = (3 + 4) / 2 = 3,5. Moyenne = 40 / 8 = 5. Les grandes valeurs 10 et 12 tirent la moyenne au-dessus de la médiane." },

  // 6.3 Variance
  { d: 6, o: "6.3", q: "Quelle est la variance de la série 1, 3, 5, 7 ?", a: ["5", "20", "√5", "6,67"], c: 0, e: "Variance d’une série statistique : x̄ = 4, carrés des écarts 9, 1, 1, 9, de somme 20. V = 20 / 4 = 5 (on divise par l’effectif n)." },
  { d: 6, o: "6.3", q: "Une série a une moyenne de 5 et la moyenne des carrés de ses valeurs vaut 30. Quelle est sa variance ?", a: ["5", "25", "55", "1,2"], c: 0, e: "Formule de König-Huygens : V = (moyenne des carrés) − (carré de la moyenne) = 30 − 25 = 5." },
  { d: 6, o: "6.3", q: "Une série de tailles est exprimée en cm. Dans quelle unité s’exprime sa variance ?", a: ["cm²", "cm", "Sans unité", "m"], c: 0, e: "La variance est une moyenne de carrés d’écarts : elle s’exprime dans l’unité au carré. C’est l’écart-type qui revient au cm." },
  { d: 6, o: "6.3", q: "Quelle est la variance de la série 8, 8, 8, 8 ?", a: ["0", "8", "64", "2"], c: 0, e: "Toutes les valeurs sont égales à la moyenne : tous les écarts sont nuls, donc la variance est nulle." },
  { d: 6, o: "6.3", q: "Une série a une variance de 9. On ajoute 10 à chaque valeur. Quelle est la nouvelle variance ?", a: ["9", "19", "109", "90"], c: 0, e: "Ajouter une constante décale la moyenne et toutes les valeurs d’autant : les écarts à la moyenne, donc la variance, ne changent pas." },

  // 6.4 Écart-type
  { d: 6, o: "6.4", q: "Une série statistique a une variance de 25. Quel est son écart-type ?", a: ["5", "25", "12,5", "625"], c: 0, e: "Écart-type d’une série : s = √V = √25 = 5." },
  { d: 6, o: "6.4", q: "Quel est l’écart-type de la série 1, 3, 5, 7 ?", a: ["Environ 2,24", "5", "4", "20"], c: 0, e: "La variance vaut 20 / 4 = 5, donc s = √5 ≈ 2,24. 5 est la variance, pas l’écart-type." },
  { d: 6, o: "6.4", q: "Deux séries de mesures ont la même moyenne de 50, avec des écarts-types de 2 (série A) et 15 (série B). Que peut-on dire ?", a: ["La série B est plus dispersée que la série A", "La série A est plus dispersée que la série B", "Les deux séries ont la même dispersion", "La série B a des valeurs plus élevées en moyenne"], c: 0, e: "La dispersion est d’autant plus grande que l’écart-type est grand. Deux séries de même moyenne peuvent avoir des dispersions très différentes." },
  { d: 6, o: "6.4", q: "Une série de masses a un écart-type de 2 kg. On convertit toutes les valeurs en grammes. Quel est le nouvel écart-type ?", a: ["2000 g", "2 g", "2 000 000 g", "1002 g"], c: 0, e: "Multiplier toutes les valeurs par 1000 multiplie l’écart-type par 1000 : 2000 g. C’est la variance qui serait multipliée par 10⁶." },
  { d: 6, o: "6.4", q: "Série A : 10, 10, 10, 10 ; série B : 5, 10, 10, 15. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["Les deux séries ont la même moyenne", "L’écart-type de A est nul", "Les deux séries ont le même écart-type", "L’écart-type de B est nul", "La série A est plus dispersée que la série B"], c: [0, 1], e: "Les deux moyennes valent 10. A ne présente aucune dispersion (écart-type nul) ; B est dispersée (écart-type ≈ 3,5)." },

  // 6.5 Quartiles
  { d: 6, o: "6.5", q: "Série ordonnée de 8 valeurs : 2, 4, 5, 7, 8, 10, 12, 15. Avec la définition du cours (plus petite valeur telle qu’au moins 25 % ou 75 % des données lui soient inférieures ou égales), que valent Q1 et Q3 ?", a: ["Q1 = 4 et Q3 = 10", "Q1 = 5 et Q3 = 12", "Q1 = 2 et Q3 = 15", "Q1 = 7 et Q3 = 8"], c: 0, e: "Premier quartile : 8 × 0,25 = 2, c’est la 2ᵉ valeur, soit 4. Troisième quartile : 8 × 0,75 = 6, c’est la 6ᵉ valeur, soit 10." },
  { d: 6, o: "6.5", q: "Une série a pour premier quartile 12 et pour troisième quartile 20. Quel est son écart interquartile ?", a: ["8", "16", "32", "4"], c: 0, e: "Écart interquartile = Q3 − Q1 = 20 − 12 = 8." },
  { d: 6, o: "6.5", q: "Dans un service, le premier quartile des poids des patients vaut 60 kg. Que signifie ce résultat ?", a: ["Au moins 25 % des patients pèsent 60 kg ou moins", "25 % des patients pèsent exactement 60 kg", "Au moins 75 % des patients pèsent 60 kg ou moins", "Le poids moyen est de 60 kg"], c: 0, e: "Q1 est la plus petite valeur telle qu’au moins 25 % des données lui soient inférieures ou égales." },
  { d: 6, o: "6.5", q: "Série ordonnée de 10 valeurs : 3, 5, 6, 8, 9, 11, 13, 14, 18, 20. Avec la définition du cours, que vaut le premier quartile Q1 ?", a: ["6", "5", "5,5", "8"], c: 0, e: "10 × 0,25 = 2,5, arrondi à l’entier supérieur : Q1 est la 3ᵉ valeur, soit 6. (Q3 : 10 × 0,75 = 7,5, donc la 8ᵉ valeur, 14.)" },
  { d: 6, o: "6.5", q: "Quel indicateur de dispersion est peu sensible aux valeurs extrêmes ?", a: ["L’écart interquartile", "L’écart-type", "La variance", "L’étendue (max − min)"], c: 0, e: "L’écart interquartile ne dépend que de la moitié centrale des données. L’écart-type, la variance et l’étendue sont fortement influencés par les valeurs extrêmes." },
  { d: 6, o: "6.5", q: "Pour des glycémies à jeun, le troisième quartile vaut 1,20 g/L. Que signifie ce résultat ?", a: ["Au moins 75 % des glycémies sont inférieures ou égales à 1,20 g/L", "75 % des patients sont diabétiques", "Au moins 25 % des glycémies sont inférieures ou égales à 1,20 g/L, et pas davantage", "La glycémie moyenne vaut 1,20 g/L"], c: 0, e: "Le troisième quartile Q3 est la plus petite valeur telle qu’au moins 75 % des données lui soient inférieures ou égales." },

  // 6.6 Représentations graphiques
  { d: 6, o: "6.6", q: "Quel graphique convient pour représenter la répartition des groupes sanguins (A, B, AB, O) d’un échantillon de donneurs ?", a: ["Un diagramme en barres", "Un histogramme", "Une boîte à moustaches", "Une courbe en cloche"], c: 0, e: "Le groupe sanguin est une variable qualitative : on utilise un diagramme en barres (ou un diagramme circulaire). L’histogramme est réservé aux variables quantitatives continues." },
  { d: 6, o: "6.6", q: "Dans un histogramme dont les classes ont des amplitudes inégales, qu’est-ce qui doit être proportionnel à l’effectif de chaque classe ?", a: ["L’aire du rectangle", "La hauteur du rectangle", "La largeur du rectangle", "Le périmètre du rectangle"], c: 0, e: "Dans un histogramme, c’est l’aire qui représente l’effectif. Avec des classes inégales, la hauteur doit donc être l’effectif divisé par l’amplitude." },
  { d: 6, o: "6.6", q: "Dans une boîte à moustaches, entre quelles valeurs s’étend la boîte ?", a: ["Du premier au troisième quartile, avec un trait à la médiane", "Du minimum au maximum, avec un trait à la moyenne", "De la moyenne moins un écart-type à la moyenne plus un écart-type", "Du premier décile au neuvième décile, avec un trait au mode"], c: 0, e: "La boîte va de Q1 à Q3 (sa longueur est l’écart interquartile) et la médiane y est marquée par un trait. Les moustaches s’étendent vers les valeurs extrêmes." },
  { d: 6, o: "6.6", q: "On a regroupé les âges de 500 patients en classes [20 ; 30[, [30 ; 40[… Quel graphique utiliser ?", a: ["Un histogramme", "Un diagramme en barres séparées", "Un diagramme circulaire", "Un tableau de contingence"], c: 0, e: "L’âge est une variable quantitative continue regroupée en classes : on utilise un histogramme, dont les rectangles sont accolés." },
  { d: 6, o: "6.6", q: "Sur une boîte à moustaches, la médiane est proche de Q1 et la moustache de droite est très longue. Que peut-on en déduire ?", a: ["La distribution est asymétrique, étalée vers les grandes valeurs", "La distribution est symétrique", "La moyenne est inférieure à la médiane", "Il y a une erreur de construction"], c: 0, e: "Une médiane décentrée vers Q1 et une longue moustache droite traduisent une asymétrie vers les grandes valeurs, comme pour les durées de séjour." },

  // ── Domaine 7 : Biostatistiques médicales ───────────────────────────────
  // 7.1 Prévalence
  { d: 7, o: "7.1", q: "Dans un collège de 2400 élèves, 120 sont asthmatiques au jour de l’enquête. Quelle est la prévalence de l’asthme ?", a: ["5 %", "20 %", "0,5 %", "12 %"], c: 0, e: "Calcul de la prévalence : cas existants / population totale = 120 / 2400 = 0,05, soit 5 %." },
  { d: 7, o: "7.1", q: "Que mesure la prévalence d’une maladie ?", a: ["La proportion de personnes atteintes dans une population à un instant donné", "Le nombre de nouveaux cas apparus pendant une période", "La probabilité de décéder de la maladie", "La vitesse de propagation de la maladie"], c: 0, e: "Définition de la prévalence : proportion de cas existants à un instant donné (le « stock » de malades). Les nouveaux cas relèvent de l’incidence." },
  { d: 7, o: "7.1", q: "Quelle est la nature de la prévalence ?", a: ["Une proportion sans unité, comprise entre 0 et 1", "Un taux exprimé en personnes-années", "Un nombre de nouveaux cas", "Un rapport de risques"], c: 0, e: "La prévalence rapporte des malades à une population qui les contient : c’est une proportion sans unité." },
  { d: 7, o: "7.1", q: "Une région de 50 000 habitants compte 750 personnes atteintes d’une maladie chronique au 1er janvier. Quelle est la prévalence à cette date ?", a: ["1,5 %", "15 %", "0,15 %", "6,7 %"], c: 0, e: "750 / 50 000 = 0,015, soit 1,5 %." },
  { d: 7, o: "7.1", q: "Une ville de 20 000 habitants compte 400 malades au 1er janvier ; 100 nouveaux cas apparaissent dans l’année. Quelle est la prévalence au 1er janvier ?", a: ["2 %", "2,5 %", "0,5 %", "0,52 %"], c: 0, e: "La prévalence au 1er janvier ne compte que les cas existants à cette date : 400 / 20 000 = 2 %. Les 100 nouveaux cas concernent l’incidence de l’année." },
  { d: 7, o: "7.1", q: "Un nouveau traitement prolonge la survie des malades sans les guérir. Quel est son effet attendu sur la prévalence de la maladie ?", a: ["Elle augmente", "Elle diminue", "Elle ne change pas", "Elle devient égale à l’incidence"], c: 0, e: "Les malades restent plus longtemps dans la population : le « stock » de cas existants augmente, sans changement du nombre de nouveaux cas." },

  // 7.2 Incidence
  { d: 7, o: "7.2", q: "Sur 3000 personnes indemnes suivies pendant un an, 45 développent la maladie. Quelle est l’incidence cumulée sur un an ?", a: ["1,5 %", "4,5 %", "0,15 %", "45"], c: 0, e: "Incidence cumulée = nouveaux cas / personnes à risque au début = 45 / 3000 = 1,5 % par an." },
  { d: 7, o: "7.2", q: "Une cohorte totalise 2500 personnes-années de suivi, pendant lesquelles 10 nouveaux cas apparaissent. Quel est le taux d’incidence ?", a: ["4 pour 1000 personnes-années", "0,4 pour 1000 personnes-années", "25 pour 1000 personnes-années", "40 pour 1000 personnes-années"], c: 0, e: "Taux d’incidence = 10 / 2500 = 0,004 par personne-année, soit 4 pour 1000 personnes-années." },
  { d: 7, o: "7.2", q: "Que place-t-on au dénominateur de l’incidence cumulée ?", a: ["Le nombre de personnes à risque (indemnes) au début de la période", "La population totale, malades compris", "Le nombre de malades", "Le nombre de décès"], c: 0, e: "L’incidence mesure l’apparition de nouveaux cas chez des personnes qui pouvaient devenir malades : les personnes déjà malades en sont exclues." },
  { d: 7, o: "7.2", q: "Une maladie aiguë, qui dure quelques jours, touche beaucoup de personnes chaque hiver. Quelle situation est typique ?", a: ["Une incidence élevée et une prévalence faible", "Une incidence faible et une prévalence élevée", "Une incidence et une prévalence nulles", "Une prévalence toujours égale à l’incidence"], c: 0, e: "Prévalence vs incidence : beaucoup de nouveaux cas (flux élevé) mais une durée très courte, donc peu de malades à un instant donné (stock faible)." },
  { d: 7, o: "7.2", q: "En situation stable, une maladie a une incidence de 2 pour 1000 par an et une durée moyenne de 5 ans. Quelle est sa prévalence approximative ?", a: ["1 %", "0,2 %", "0,4 %", "10 %"], c: 0, e: "Prévalence ≈ incidence × durée moyenne = 0,002 × 5 = 0,01, soit 1 %." },
  { d: 7, o: "7.2", q: "Quelles affirmations sur la prévalence et l’incidence sont vraies ? (Choisissez 2 réponses)", a: ["L’incidence compte les nouveaux cas apparus pendant une période", "La prévalence compte les cas existants à un instant donné", "Guérir plus vite les malades augmente la prévalence", "L’incidence inclut les personnes déjà malades au début de la période", "La prévalence est toujours inférieure à l’incidence"], c: [0, 1], e: "Incidence = flux de nouveaux cas ; prévalence = stock de cas existants. Guérir plus vite raccourcit la durée et diminue la prévalence. Selon la durée de la maladie, la prévalence peut être supérieure ou inférieure à l’incidence." },

  // 7.3 Sensibilité
  { d: 7, o: "7.3", q: "Sur 200 malades, un test est positif chez 170 et négatif chez 30. Quelle est sa sensibilité ?", a: ["85 %", "15 %", "17,6 %", "70 %"], c: 0, e: "Calcul de la sensibilité : Se = VP / (VP + FN) = 170 / 200 = 85 %." },
  { d: 7, o: "7.3", q: "Quelle probabilité conditionnelle correspond à la sensibilité d’un test ?", a: ["P(T+ | M)", "P(M | T+)", "P(T− | M̄)", "P(M̄ | T−)"], c: 0, e: "La sensibilité est la probabilité d’un test positif chez les malades. P(M | T+) est la valeur prédictive positive." },
  { d: 7, o: "7.3", q: "Un test a une sensibilité de 95 %. Sur 400 malades testés, combien de faux négatifs attend-on ?", a: ["20", "380", "5", "40"], c: 0, e: "La proportion de faux négatifs parmi les malades vaut 1 − Se = 5 %, soit 0,05 × 400 = 20 faux négatifs." },
  { d: 7, o: "7.3", q: "Pour un dépistage où il est essentiel de ne manquer aucun malade, quel type de test privilégier ?", a: ["Un test très sensible", "Un test très spécifique", "Un test à forte VPP", "Un test peu coûteux, quelles que soient ses qualités"], c: 0, e: "Un test très sensible produit peu de faux négatifs : s’il est négatif, il permet d’écarter la maladie. C’est la qualité recherchée en dépistage." },
  { d: 7, o: "7.3", q: "Dans le tableau de contingence d’un test diagnostique, comment appelle-t-on un malade dont le test est négatif ?", a: ["Un faux négatif", "Un faux positif", "Un vrai négatif", "Un vrai positif"], c: 0, e: "Le test dit « négatif » à tort, puisque la personne est malade : c’est un faux négatif (FN)." },
  { d: 7, o: "7.3", q: "Un test est évalué sur 500 malades et 1500 non-malades : 450 malades sont positifs et 1350 non-malades sont négatifs. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["La sensibilité vaut 90 %", "Il y a 50 faux négatifs", "Il y a 150 faux négatifs", "La sensibilité vaut 450 / 1800", "Il y a 50 faux positifs"], c: [0, 1], e: "Se = 450 / 500 = 90 % et FN = 500 − 450 = 50. Les non-malades positifs sont 1500 − 1350 = 150 faux positifs. Le dénominateur de Se est le nombre de malades, pas le nombre de positifs." },

  // 7.4 Spécificité
  { d: 7, o: "7.4", q: "Sur 800 non-malades, un test est négatif chez 720 et positif chez 80. Quelle est sa spécificité ?", a: ["90 %", "10 %", "11 %", "80 %"], c: 0, e: "Calcul de la spécificité : Sp = VN / (VN + FP) = 720 / 800 = 90 %." },
  { d: 7, o: "7.4", q: "Quelle probabilité conditionnelle correspond à la spécificité d’un test ?", a: ["P(T− | M̄)", "P(T+ | M)", "P(M̄ | T−)", "P(M | T+)"], c: 0, e: "La spécificité est la probabilité d’un test négatif chez les non-malades. P(M̄ | T−) est la valeur prédictive négative." },
  { d: 7, o: "7.4", q: "Un test a une spécificité de 98 %. Sur 5000 non-malades testés, combien de faux positifs attend-on ?", a: ["100", "4900", "98", "2"], c: 0, e: "La proportion de faux positifs parmi les non-malades vaut 1 − Sp = 2 %, soit 0,02 × 5000 = 100." },
  { d: 7, o: "7.4", q: "Avant d’engager un traitement lourd, on veut confirmer un diagnostic. Quel type de test privilégier ?", a: ["Un test très spécifique", "Un test très sensible", "Un test à forte VPN", "Un test de dépistage de masse"], c: 0, e: "Un test très spécifique produit peu de faux positifs : s’il est positif, il permet de confirmer la maladie." },
  { d: 7, o: "7.4", q: "Pour un marqueur sanguin, on abaisse le seuil au-delà duquel le test est déclaré positif. Quel est l’effet attendu ?", a: ["La sensibilité augmente et la spécificité diminue", "La sensibilité et la spécificité augmentent", "La sensibilité diminue et la spécificité augmente", "Aucun effet sur la sensibilité ni la spécificité"], c: 0, e: "Compromis sensibilité-spécificité : plus de personnes sont déclarées positives, donc moins de faux négatifs (Se ↑) mais plus de faux positifs (Sp ↓)." },
  { d: 7, o: "7.4", q: "La sensibilité et la spécificité d’un test dépendent-elles de la prévalence de la maladie dans la population testée ?", a: ["Non, ce sont des qualités intrinsèques du test", "Oui, elles augmentent avec la prévalence", "Oui, elles diminuent avec la prévalence", "Seule la spécificité en dépend"], c: 0, e: "Se et Sp se calculent séparément chez les malades et chez les non-malades : elles ne dépendent pas de la proportion de malades. Ce sont les valeurs prédictives qui en dépendent." },

  // 7.5 Valeur prédictive positive
  { d: 7, o: "7.5", q: "Parmi 100 personnes testées positives, 80 sont réellement malades. Quelle est la valeur prédictive positive du test ?", a: ["80 %", "20 %", "25 %", "Impossible à calculer sans la sensibilité"], c: 0, e: "Calcul de la VPP : VPP = VP / (VP + FP) = 80 / 100 = 80 %." },
  { d: 7, o: "7.5", q: "Quelle probabilité conditionnelle correspond à la valeur prédictive positive ?", a: ["P(M | T+)", "P(T+ | M)", "P(M̄ | T−)", "P(T− | M̄)"], c: 0, e: "La VPP est la probabilité d’être malade quand le test est positif. P(T+ | M) est la sensibilité." },
  { d: 7, o: "7.5", q: "À sensibilité et spécificité fixées, comment évolue la VPP quand la prévalence augmente ?", a: ["Elle augmente", "Elle diminue", "Elle ne change pas", "Elle devient égale à la sensibilité"], c: 0, e: "Influence de la prévalence sur la VPP : plus il y a de malades, plus les vrais positifs pèsent face aux faux positifs." },
  { d: 7, o: "7.5", q: "Un test a une sensibilité et une spécificité de 90 %. On l’utilise en dépistage de masse, avec une prévalence de 1 %. Quelle est sa VPP ?", a: ["Environ 8,3 %", "90 %", "1 %", "50 %"], c: 0, e: "Sur 10 000 personnes : 100 malades donnent 90 VP ; 9900 non-malades donnent 990 FP. VPP = 90 / 1080 ≈ 8,3 % : la grande majorité des positifs sont des faux positifs." },
  { d: 7, o: "7.5", q: "Le même test (sensibilité et spécificité de 90 %) est utilisé chez des patients symptomatiques, où la prévalence atteint 50 %. Quelle est sa VPP ?", a: ["90 %", "50 %", "8,3 %", "45 %"], c: 0, e: "Sur 10 000 personnes : 5000 malades donnent 4500 VP ; 5000 non-malades donnent 500 FP. VPP = 4500 / 5000 = 90 %." },
  { d: 7, o: "7.5", q: "Sur 1000 personnes testées : VP = 60, FP = 40, FN = 15, VN = 885. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["La VPP vaut 60 %", "La prévalence dans cet échantillon est de 7,5 %", "La VPP vaut 80 %", "La sensibilité vaut 60 %", "La VPN vaut 885 / 925"], c: [0, 1], e: "VPP = 60 / (60 + 40) = 60 % ; prévalence = (60 + 15) / 1000 = 7,5 %. Se = 60 / 75 = 80 % ; VPN = 885 / (885 + 15) = 885 / 900." },

  // 7.6 Valeur prédictive négative
  { d: 7, o: "7.6", q: "Parmi 960 personnes testées négatives, 940 ne sont pas malades et 20 le sont. Quelle est la valeur prédictive négative ?", a: ["Environ 97,9 %", "Environ 2,1 %", "94 %", "Environ 99,5 %"], c: 0, e: "Calcul de la VPN : VPN = VN / (VN + FN) = 940 / 960 ≈ 97,9 %." },
  { d: 7, o: "7.6", q: "Quelle probabilité conditionnelle correspond à la valeur prédictive négative ?", a: ["P(M̄ | T−)", "P(T− | M̄)", "P(M | T+)", "P(T+ | M)"], c: 0, e: "La VPN est la probabilité de ne pas être malade quand le test est négatif. P(T− | M̄) est la spécificité." },
  { d: 7, o: "7.6", q: "À sensibilité et spécificité fixées, comment évolue la VPN quand la prévalence augmente ?", a: ["Elle diminue", "Elle augmente", "Elle ne change pas", "Elle devient égale à la spécificité"], c: 0, e: "Influence de la prévalence sur la VPN : plus il y a de malades, plus il y a de faux négatifs parmi les négatifs." },
  { d: 7, o: "7.6", q: "Un test a une sensibilité de 80 % et une spécificité de 90 %, avec une prévalence de 20 %. Quelle est sa VPN ?", a: ["Environ 94,7 %", "90 %", "80 %", "72 %"], c: 0, e: "Sur 1000 personnes : 200 malades (160 VP, 40 FN) et 800 non-malades (720 VN, 80 FP). VPN = 720 / (720 + 40) ≈ 94,7 %." },
  { d: 7, o: "7.6", q: "Un test a une VPN de 99 %. Que signifie ce résultat ?", a: ["Parmi les personnes testées négatives, 99 % ne sont pas malades", "Parmi les non-malades, 99 % ont un test négatif", "Le test détecte 99 % des malades", "99 % des personnes testées sont négatives"], c: 0, e: "La VPN se calcule parmi les personnes ayant un test négatif. « 99 % des non-malades sont négatifs » décrit la spécificité." },
  { d: 7, o: "7.6", q: "Quelle est la différence de calcul entre les valeurs prédictives (VPP, VPN) et la sensibilité ou la spécificité ?", a: ["Les valeurs prédictives se calculent parmi les personnes ayant un même résultat de test ; Se et Sp parmi celles ayant un même statut réel", "Les valeurs prédictives se calculent parmi les malades ; Se et Sp parmi les personnes testées", "Il n’y a aucune différence", "Les valeurs prédictives ne dépendent que de la sensibilité"], c: 0, e: "VPP = P(M | T+) et VPN = P(M̄ | T−) conditionnent sur le résultat du test ; Se = P(T+ | M) et Sp = P(T− | M̄) conditionnent sur le statut réel." },

  // 7.7 Risque relatif
  { d: 7, o: "7.7", q: "Dans une étude de cohorte, 40 des 500 exposés et 20 des 1000 non-exposés développent la maladie. Quel est le risque relatif ?", a: ["4", "2", "0,25", "0,06"], c: 0, e: "Calcul du risque relatif : risque chez les exposés 40/500 = 0,08 ; chez les non-exposés 20/1000 = 0,02. RR = 0,08 / 0,02 = 4. Comparer les nombres bruts de cas (40/20 = 2) oublie la différence d’effectifs." },
  { d: 7, o: "7.7", q: "Une étude trouve un risque relatif de 1 entre une exposition et une maladie. Comment l’interpréter ?", a: ["Il n’y a pas d’association entre l’exposition et la maladie", "L’exposition double le risque", "Tous les exposés sont malades", "L’exposition protège de la maladie"], c: 0, e: "Interprétation du risque relatif : RR = 1 signifie que le risque est le même chez les exposés et chez les non-exposés." },
  { d: 7, o: "7.7", q: "Dans une cohorte, un traitement préventif est associé à un risque relatif de 0,5. Comment l’interpréter ?", a: ["Le risque est divisé par 2 chez les personnes traitées : facteur protecteur", "Le risque est multiplié par 2 chez les personnes traitées", "La moitié des traités tombent malades", "Il n’y a pas d’association"], c: 0, e: "RR < 1 : le risque est plus faible chez les exposés (ici traités). RR = 0,5 correspond à un risque divisé par 2." },
  { d: 7, o: "7.7", q: "Quel type d’étude permet de calculer directement un risque relatif ?", a: ["Une étude de cohorte", "Une étude cas-témoins", "Une série de cas", "Une étude sans groupe de comparaison"], c: 0, e: "L’étude de cohorte suit des exposés et des non-exposés et compte les nouveaux cas : on peut y calculer des risques, donc leur rapport." },
  { d: 7, o: "7.7", q: "Dans une cohorte, a = 15 exposés malades, b = 85 exposés non malades, c = 5 non-exposés malades, d = 95 non-exposés non malades. Quel est le risque relatif ?", a: ["3", "Environ 3,35", "Environ 0,33", "10"], c: 0, e: "RR = [a/(a + b)] / [c/(c + d)] = (15/100) / (5/100) = 3. 3,35 est l’odds ratio (a·d)/(b·c) = 1425 / 425." },
  { d: 7, o: "7.7", q: "Dans une cohorte, le risque de maladie est de 6 % chez les exposés et de 2 % chez les non-exposés. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["Le risque relatif vaut 3", "L’exposition est associée à une augmentation du risque", "Le risque relatif vaut 4", "L’exposition est un facteur protecteur", "Cette étude prouve à elle seule que l’exposition cause la maladie"], c: [0, 1], e: "RR = 6 % / 2 % = 3 > 1 : l’exposition est associée à un risque accru. Une association statistique ne prouve pas à elle seule une causalité. 4 % est la différence de risques, pas le RR." },

  // 7.8 Odds ratio
  { d: 7, o: "7.8", q: "Étude cas-témoins : parmi 100 cas, 60 ont été exposés ; parmi 100 témoins, 30 ont été exposés. Quel est l’odds ratio ?", a: ["3,5", "2", "Environ 0,29", "1,5"], c: 0, e: "Calcul de l’odds ratio avec a = 60, b = 30, c = 40, d = 70 : OR = (a × d)/(b × c) = (60 × 70)/(30 × 40) = 4200 / 1200 = 3,5." },
  { d: 7, o: "7.8", q: "Pourquoi ne peut-on pas calculer de risque relatif dans une étude cas-témoins ?", a: ["Parce que la proportion de malades dans l’étude est fixée par l’enquêteur", "Parce qu’il n’y a pas de groupe témoin", "Parce que l’exposition n’est pas mesurée", "Parce que l’effectif est toujours trop faible"], c: 0, e: "Dans une étude cas-témoins, on choisit le nombre de cas et de témoins : la fréquence de la maladie dans l’étude ne reflète pas un risque. L’odds ratio reste calculable." },
  { d: 7, o: "7.8", q: "Un événement a une probabilité p = 0,2. Quelle est sa cote (odds) ?", a: ["0,25", "0,2", "4", "0,8"], c: 0, e: "Cote = p / (1 − p) = 0,2 / 0,8 = 0,25, soit « 1 contre 4 »." },
  { d: 7, o: "7.8", q: "Dans quelle situation l’odds ratio est-il une bonne approximation du risque relatif ?", a: ["Quand la maladie est rare", "Quand la maladie est fréquente", "Quand l’odds ratio vaut 0", "Jamais"], c: 0, e: "Odds ratio vs risque relatif : quand la maladie est rare, p / (1 − p) ≈ p, et l’OR est proche du RR." },
  { d: 7, o: "7.8", q: "Une étude cas-témoins trouve un odds ratio de 0,4 pour une exposition. Comment l’interpréter ?", a: ["L’exposition est associée à une moindre fréquence de la maladie (facteur protecteur)", "L’exposition multiplie le risque par 2,5", "40 % des exposés sont malades", "Il n’y a pas d’association"], c: 0, e: "Comme pour le RR, OR < 1 signifie une association négative : l’exposition est associée à une cote de maladie plus faible." },
  { d: 7, o: "7.8", q: "Dans une cohorte, 50 des 100 exposés et 25 des 100 non-exposés sont malades. Que valent le risque relatif et l’odds ratio ?", a: ["RR = 2 et OR = 3", "RR = 3 et OR = 2", "RR = OR = 2", "RR = 2 et OR = 1,5"], c: 0, e: "RR = 0,50 / 0,25 = 2. OR = (50 × 75)/(50 × 25) = 3. La maladie étant fréquente, l’OR s’éloigne davantage de 1 que le RR." },

  // ── Domaine 8 : Estimation, intervalles de confiance et tests statistiques ─
  // 8.1 Échantillonnage
  { d: 8, o: "8.1", q: "Pourquoi tire-t-on au sort les individus d’un échantillon dans une étude ?", a: ["Pour que l’échantillon soit représentatif de la population", "Pour obtenir un échantillon plus grand", "Pour supprimer toute fluctuation d’échantillonnage", "Pour connaître exactement la proportion de la population"], c: 0, e: "Le tirage au sort permet de généraliser les résultats à la population. Il ne supprime pas la fluctuation d’échantillonnage, qui reste due au hasard." },
  { d: 8, o: "8.1", q: "Deux échantillons de 100 patients tirés au sort dans la même population donnent des proportions de fumeurs de 32 % et 38 %. Comment l’expliquer ?", a: ["Par la fluctuation d’échantillonnage", "Par une erreur de calcul", "Par le fait que la population a changé entre les deux tirages", "Par une erreur de type II"], c: 0, e: "Deux échantillons d’une même population diffèrent naturellement : c’est la fluctuation d’échantillonnage." },
  { d: 8, o: "8.1", q: "Comment évolue la fluctuation d’échantillonnage quand la taille de l’échantillon augmente ?", a: ["Elle diminue", "Elle augmente", "Elle ne change pas", "Elle devient nulle dès n = 30"], c: 0, e: "Plus l’échantillon est grand, plus les résultats se resserrent autour de la vraie valeur (variabilité en 1/√n). Elle ne disparaît jamais complètement." },

  // 8.2 Estimation d’une proportion
  { d: 8, o: "8.2", q: "Sur 150 patients tirés au sort, 36 présentent un marqueur. Quelle est l’estimation ponctuelle de la proportion de porteurs dans la population ?", a: ["0,24", "0,36", "0,15", "24"], c: 0, e: "La proportion observée f = 36 / 150 = 0,24 est l’estimateur ponctuel de la proportion p de la population." },
  { d: 8, o: "8.2", q: "Quel est le rôle de la proportion observée f = k / n dans un échantillon ?", a: ["C’est l’estimateur ponctuel de la proportion p inconnue de la population", "C’est la valeur exacte de p", "C’est la marge d’erreur de l’estimation", "C’est la p-value de l’étude"], c: 0, e: "p est inconnue ; la proportion observée f en donne une estimation, qui varie d’un échantillon à l’autre." },
  { d: 8, o: "8.2", q: "Quelle est la principale limite d’une estimation ponctuelle donnée seule ?", a: ["Elle ne renseigne pas sur sa précision ; on l’accompagne d’un intervalle de confiance", "Elle est toujours fausse", "Elle ne peut être calculée que sur toute la population", "Elle dépend du seuil α choisi"], c: 0, e: "Une même valeur de f n’a pas la même fiabilité avec 20 ou 2000 sujets : l’intervalle de confiance traduit cette précision." },

  // 8.3 Intervalle de confiance
  { d: 8, o: "8.3", q: "Sur 100 patients, la proportion observée vaut f = 0,30. Quel est l’intervalle de confiance à 95 % de la proportion ?", a: ["Environ [0,21 ; 0,39]", "Environ [0,25 ; 0,35]", "Environ [0,29 ; 0,31]", "Environ [0,10 ; 0,50]"], c: 0, e: "IC à 95 % d’une proportion : 1,96 × √(0,3 × 0,7 / 100) = 1,96 × 0,0458 ≈ 0,09. IC ≈ [0,30 − 0,09 ; 0,30 + 0,09] = [0,21 ; 0,39]." },
  { d: 8, o: "8.3", q: "Une étude donne un IC à 95 % de la prévalence égal à [0,16 ; 0,24]. Quelle interprétation est correcte ?", a: ["Si l’on répétait l’étude un grand nombre de fois, environ 95 % des intervalles ainsi construits contiendraient la vraie prévalence", "95 % des individus de la population ont une valeur comprise entre 0,16 et 0,24", "La vraie prévalence vaut exactement 0,20", "L’intervalle contient 95 % des valeurs observées dans l’échantillon"], c: 0, e: "Interprétation de l’intervalle de confiance : il porte sur un paramètre (la prévalence), pas sur les valeurs individuelles. Le niveau 95 % décrit la fiabilité de la méthode de construction." },
  { d: 8, o: "8.3", q: "À partir des mêmes données, comment se compare un IC à 99 % à un IC à 95 % ?", a: ["Il est plus large", "Il est plus étroit", "Il est identique", "Il est décalé vers les grandes valeurs"], c: 0, e: "Pour être plus confiant de contenir la vraie valeur, l’intervalle doit être plus large (1,96 est remplacé par 2,58) : plus de confiance, moins de précision." },
  { d: 8, o: "8.3", q: "Sur 400 patients, 80 présentent un effet indésirable. Quelles affirmations sont vraies ? (Choisissez 2 réponses)", a: ["La proportion observée vaut 0,20", "L’IC à 95 % vaut environ [0,16 ; 0,24]", "L’IC à 95 % vaut environ [0,10 ; 0,30]", "La proportion observée vaut 0,80", "Les conditions d’utilisation de l’IC ne sont pas remplies"], c: [0, 1], e: "f = 80/400 = 0,20 ; 1,96 × √(0,2 × 0,8 / 400) = 1,96 × 0,02 ≈ 0,04, d’où l’IC ≈ [0,16 ; 0,24]. Les conditions sont remplies : n = 400, nf = 80 et n(1 − f) = 320." },

  // 8.4 Marge d’erreur
  { d: 8, o: "8.4", q: "On veut diviser par 2 la marge d’erreur d’une estimation de proportion. Par combien faut-il multiplier la taille de l’échantillon ?", a: ["4", "2", "√2", "8"], c: 0, e: "La marge d’erreur est proportionnelle à 1/√n : pour la diviser par 2, il faut multiplier √n par 2, donc n par 4." },
  { d: 8, o: "8.4", q: "Dans un sondage de 400 personnes, la proportion observée vaut 0,5. Quelle est la marge d’erreur à 95 % ?", a: ["Environ 4,9 %", "2,5 %", "Environ 9,8 %", "0,5 %"], c: 0, e: "Marge d’erreur = 1,96 × √(0,5 × 0,5 / 400) = 1,96 × 0,025 ≈ 0,049. 9,8 % est la largeur totale de l’intervalle." },
  { d: 8, o: "8.4", q: "À taille d’échantillon fixée, pour quelle proportion observée f la marge d’erreur est-elle maximale ?", a: ["f = 0,5", "f = 0", "f = 1", "f = 0,05"], c: 0, e: "Le produit f(1 − f) est maximal pour f = 0,5 (il vaut alors 0,25) : c’est là que la marge d’erreur est la plus grande." },

  // 8.5 H₀ et H₁
  { d: 8, o: "8.5", q: "Un essai compare un nouveau traitement à un placebo. Quelle est l’hypothèse nulle H₀ ?", a: ["Les deux traitements ont la même efficacité", "Le nouveau traitement est plus efficace", "Le placebo est plus efficace", "Les deux traitements sont inefficaces"], c: 0, e: "L’hypothèse nulle est l’hypothèse d’absence de différence. Ce que l’on cherche à montrer (une différence) est l’hypothèse alternative H₁." },
  { d: 8, o: "8.5", q: "Dans un test bilatéral comparant deux traitements, quelle est l’hypothèse alternative H₁ ?", a: ["Les efficacités des deux traitements diffèrent", "Les efficacités sont égales", "Le traitement A est plus efficace que B", "Le traitement B est plus efficace que A"], c: 0, e: "En bilatéral, H₁ admet une différence dans les deux sens. « A plus efficace que B » correspond à un test unilatéral." },
  { d: 8, o: "8.5", q: "Sous quelle hypothèse calcule-t-on la p-value d’un test ?", a: ["En supposant H₀ vraie", "En supposant H₁ vraie", "Sans aucune hypothèse", "En supposant que l’effet observé est réel"], c: 0, e: "Le test est construit sous H₀ : on évalue à quel point les données observées seraient surprenantes si H₀ était vraie." },
  { d: 8, o: "8.5", q: "Avant l’étude, un laboratoire décide de tester en unilatéral si son médicament fait baisser la tension davantage que le placebo. Quelle est l’hypothèse alternative H₁ ?", a: ["La baisse moyenne de tension est plus grande sous médicament que sous placebo", "Les baisses moyennes sont égales", "Les baisses moyennes diffèrent, dans un sens ou dans l’autre", "Le médicament augmente la tension"], c: 0, e: "Un test unilatéral fixe le sens de la différence dans H₁. « Égales » est H₀, et « diffèrent dans un sens ou dans l’autre » correspond au bilatéral." },

  // 8.6 p-value
  { d: 8, o: "8.6", q: "Quelle est la définition de la p-value ?", a: ["La probabilité, si H₀ est vraie, d’observer un résultat au moins aussi éloigné de H₀ que celui obtenu", "La probabilité que H₀ soit vraie", "La probabilité que H₁ soit vraie", "La probabilité que le résultat soit cliniquement important"], c: 0, e: "La p-value se calcule en supposant H₀ vraie. Ce n’est ni la probabilité de H₀, ni celle de H₁, ni une mesure de l’importance de l’effet." },
  { d: 8, o: "8.6", q: "Un essai obtient p = 0,03 avec un seuil α = 5 %. Quelle est la conclusion ?", a: ["On rejette H₀ : la différence est statistiquement significative", "On ne rejette pas H₀", "On démontre que H₀ est vraie", "On ne peut pas conclure"], c: 0, e: "p = 0,03 ≤ 0,05 : on rejette H₀ au seuil de 5 %." },
  { d: 8, o: "8.6", q: "Un essai obtient p = 0,20 avec un seuil α = 5 %. Quelle est la conclusion correcte ?", a: ["On ne rejette pas H₀ : l’étude ne met pas en évidence de différence", "On démontre que les traitements sont équivalents", "On rejette H₀", "H₀ a 20 % de chances d’être vraie"], c: 0, e: "Interprétation de la p-value : p > α, on ne rejette pas H₀. Cela ne prouve pas l’absence de différence : l’étude a pu manquer de puissance." },
  { d: 8, o: "8.6", q: "Une étude obtient p = 0,01. Quelles affirmations sont correctes ? (Choisissez 2 réponses)", a: ["Si H₀ était vraie, un écart au moins aussi grand serait observé dans environ 1 % des études", "Au seuil de 5 %, on rejette H₀", "La probabilité que H₀ soit vraie est de 1 %", "L’effet du traitement est forcément important", "Au seuil de 5 %, on ne rejette pas H₀"], c: [0, 1], e: "La p-value mesure la compatibilité des données avec H₀ ; 0,01 ≤ 0,05 conduit au rejet. Elle ne donne ni la probabilité de H₀, ni l’ampleur de l’effet." },

  // 8.7 Seuil de significativité
  { d: 8, o: "8.7", q: "À quel moment le seuil α d’un test doit-il être fixé ?", a: ["Avant de réaliser l’étude", "Après avoir calculé la p-value", "Après avoir observé la différence entre les groupes", "Il n’a pas besoin d’être fixé"], c: 0, e: "Le seuil α est choisi avant l’étude. Le choisir après avoir vu les résultats reviendrait à adapter la règle de décision aux données." },
  { d: 8, o: "8.7", q: "On passe d’un seuil α = 5 % à un seuil α = 1 %. Quel est l’effet sur la décision ?", a: ["Rejeter H₀ devient plus difficile", "Rejeter H₀ devient plus facile", "La p-value est divisée par 5", "La puissance augmente"], c: 0, e: "Il faut désormais p ≤ 0,01 pour rejeter H₀. Le risque α diminue, mais à effectif égal la puissance diminue aussi." },
  { d: 8, o: "8.7", q: "Un test donne p = 0,04. Le seuil fixé avant l’étude était α = 1 %. Quelle est la décision ?", a: ["On ne rejette pas H₀", "On rejette H₀", "On change de seuil pour α = 5 %", "On conclut que H₁ est vraie"], c: 0, e: "Règle de décision : on rejette H₀ si p ≤ α. Ici 0,04 > 0,01, donc on ne rejette pas H₀. Changer de seuil après coup n’est pas acceptable." },

  // 8.8 Erreurs de type I et II
  { d: 8, o: "8.8", q: "Qu’est-ce qu’une erreur de type I ?", a: ["Rejeter H₀ alors qu’elle est vraie", "Ne pas rejeter H₀ alors qu’elle est fausse", "Rejeter H₀ alors qu’elle est fausse", "Se tromper dans le calcul de la p-value"], c: 0, e: "L’erreur de type I (risque α) consiste à conclure à tort à une différence : un « faux positif » statistique." },
  { d: 8, o: "8.8", q: "Qu’est-ce qu’une erreur de type II ?", a: ["Ne pas rejeter H₀ alors qu’elle est fausse", "Rejeter H₀ alors qu’elle est vraie", "Choisir un seuil α trop élevé", "Utiliser un test unilatéral au lieu d’un test bilatéral"], c: 0, e: "L’erreur de type II (risque β) consiste à passer à côté d’un effet réel : un « faux négatif » statistique." },
  { d: 8, o: "8.8", q: "Un essai est conçu avec un risque β de 20 %. Quelle est sa puissance ?", a: ["80 %", "20 %", "5 %", "95 %"], c: 0, e: "Puissance = 1 − β = 0,80 : l’essai a 80 % de chances de mettre en évidence l’effet s’il existe réellement avec l’ampleur prévue." },
  { d: 8, o: "8.8", q: "Quels moyens augmentent la puissance d’un essai ? (Choisissez 2 réponses)", a: ["Augmenter la taille de l’échantillon", "Étudier un effet réel de plus grande ampleur", "Diminuer α à effectif constant", "Diminuer la taille de l’échantillon", "Augmenter β"], c: [0, 1], e: "La puissance augmente avec l’effectif et avec l’ampleur de l’effet réel. Diminuer α à effectif fixé augmente β, donc diminue la puissance (1 − β)." },

  // 8.9 Interprétation des résultats
  { d: 8, o: "8.9", q: "Un essai sur 100 000 patients montre une baisse de tension de 1 mmHg sous traitement, avec p < 0,001. Comment l’interpréter ?", a: ["Le résultat est statistiquement significatif, mais son intérêt clinique est probablement faible", "Le traitement est très efficace, car p est très petit", "Le résultat est dû au hasard", "Le résultat n’est pas significatif"], c: 0, e: "Avec un très grand effectif, une différence minime devient significative. La significativité statistique ne dit rien de la pertinence clinique, qui dépend de l’ampleur de l’effet." },
  { d: 8, o: "8.9", q: "Un petit essai de 30 patients ne trouve pas de différence significative entre deux traitements (p = 0,25). Que peut-on conclure ?", a: ["L’étude a pu manquer de puissance ; on ne peut pas conclure à l’absence d’effet", "Les deux traitements sont équivalents", "Le nouveau traitement est inefficace", "Il faut changer de seuil pour obtenir un résultat significatif"], c: 0, e: "Absence de preuve n’est pas preuve d’absence : avec un petit effectif, la puissance est faible et un effet réel peut passer inaperçu." },
  { d: 8, o: "8.9", q: "On réalise 20 tests indépendants au seuil de 5 %, et H₀ est vraie pour chacun. Combien de résultats significatifs attend-on en moyenne, par le seul hasard ?", a: ["1", "0", "5", "20"], c: 0, e: "Chaque test a 5 % de risque de rejeter H₀ à tort : 20 × 0,05 = 1 résultat significatif attendu par hasard. Multiplier les tests augmente le risque de fausse découverte." },
  { d: 8, o: "8.9", q: "Pour juger de la pertinence clinique d’un résultat, que faut-il examiner en priorité ?", a: ["L’ampleur de l’effet et son intervalle de confiance", "La p-value seule", "Le nombre de tests réalisés", "La valeur du seuil α"], c: 0, e: "La pertinence clinique s’apprécie sur la taille de l’effet et sa précision (IC), pas sur la p-value seule." }
];
